window.QUOTES={"FED|OMB M-25-21":{"meta":{"version":"Official memo (PDF)","date":"2025","textUrl":"https://www.whitehouse.gov/wp-content/uploads/2025/02/M-25-21-Accelerating-Federal-Use-of-AI-through-Innovation-Governance-and-Public-Trust.pdf","stateUrl":"","legiscan":""},"q":[{"part":"I","supported":"yes","quote":"Each agency (except for the Department of Defense and the Intelligence Community) must inventory its AI use cases at least annually, submit the inventory to 0MB, and post a public version on the agency's website.","where":"Section 3(b)(v)","specifics":"Each covered federal agency must inventory its AI use cases at least annually, send the inventory to OMB, and post a public version on its website.","note":"Text OCR shows OMB as '0MB'.","caveat":""},{"part":"A","supported":"yes","quote":"Agencies must complete an AI impact assessment before deploying any high-impact AI use case.","where":"Section 4(b)(ii)","specifics":"Before deploying any high-impact AI use case, the agency must complete (and keep updated) a documented AI impact assessment; Section 4(b)(i) also requires pre-deployment testing.","note":"","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"yes","quote":"Agencies must conduct testing and periodic human review of AI use cases, where feasible, to identify any adverse impacts to the performance and security of AI functionality, including those that may violate laws governing privacy, civil rights, or civil liberties.","where":"Section 4(b)(iii)","specifics":"Agencies must run ongoing testing and periodic human review of high-impact AI to detect adverse impacts, including civil-rights violations, and implement mitigations.","note":"Ongoing monitoring part of A; no explicit bias-testing or mandatory discontinuation wording except Section 4(b)(i)-style termination of non-compliant AI.","caveat":"limited by conditions or exceptions. Quote has 'where feasible' and 'periodic'; specifics says 'must run ongoing testing' without that qualifier; waivers/pilot exemption also apply."},{"part":"H","supported":"yes","quote":"Agencies must ensure that individuals affected by AI-enabled decisions have access to a timely human review and a chance to appeal any negative impacts, when appropriate.","where":"Section 4(b)(vi)","specifics":"For high-impact AI, agencies must give affected individuals timely human review and a chance to appeal negative impacts, 'when appropriate', and may reuse existing appeals processes.","note":"Qualified by 'when appropriate'.","caveat":"limited by conditions or exceptions"},{"part":"O","supported":"partial","quote":"the head of each agency must retain or designate a Chief AI Officer (CAIO).","where":"Section 3(a)(i)","specifics":"Within 60 days each agency head must designate a Chief AI Officer who runs agency AI governance and oversight; there is no external enforcement body or penalty.","note":"Internal agency oversight only; no external enforcement.","caveat":"Quote is the CAIO designation only; text says CAIO will 'promote AI innovation, adoption, and governance', so 'runs agency AI governance and oversight' is a stretch. 60 days and no external enforcement are correct."},{"part":"SCOPE","supported":"yes","quote":"m. Ability to apply for, or adjudication of, requests for critical federal services, processes, and benefits to include loans and access to public housing; determination of continued eligibility for ongoing benefits;","where":"Section 6(m) (presumed high-impact uses)","specifics":"Uses that decide applications for federal services and benefits or continued benefit eligibility are presumed high-impact and so trigger the minimum practices.","note":"Section 6(m) also lists detection of fraudulent use of government services and adjudication of penalties in the context of government benefits.","caveat":"a definition, not itself a duty; limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"AI is considered high-impact when its output serves as a principal basis for decisions or actions that have a legal, material, binding, or significant effect on rights or safety.","where":"Section 4(a)","specifics":"Minimum practices apply only to federal agency AI whose output is a principal basis for decisions with legal, material, binding or significant effect on rights or safety.","note":"Federal agencies only; does not cover states.","caveat":"a definition, not itself a duty"},{"part":"N","supported":"no","quote":"","where":"Section 4(b)","specifics":"The memo has no requirement to notify affected people that AI was used or to explain adverse decisions; only an option to submit feedback (Section 4(b)(vii)) and notice for pilot opt-outs.","note":"Not tagged; reported as absent."}]},"FED|OMB M-25-22":{"meta":{"version":"Official memo (PDF)","date":"2025","textUrl":"https://www.whitehouse.gov/wp-content/uploads/2025/02/M-25-22-Driving-Efficient-Acquisition-of-Artificial-Intelligence-in-Government.pdf","stateUrl":"","legiscan":""},"q":[{"part":"V","supported":"yes","quote":"agencies must inform vendors of reasonable transparency and documentation requirements that will be placed on the vendor to enable agency compliance with the requirements in 0MB Memorandum M-25-21. For example, agencies should require sufficient descriptive information from vendors to complete the required AI Impact Assessment for high-impact use cases.","where":"Section 4","specifics":"For AI with likely high-impact uses, agencies must tell vendors up front what documentation they must supply and should require enough information from vendors to complete the M-25-21 impact assessment.","note":"Memo text is available (earlier summary said it was not retrieved).","caveat":"limited by conditions or exceptions. Wrong section: 3(c) is not this text. Also only for AI with potential or expected high-impact uses; the 'should require' sentence is advisory."},{"part":"V","supported":"yes","quote":"Vendors must provide the access and time necessary for agencies to complete independent evaluation.","where":"Section 4","specifics":"Contracts must require vendors to give agencies the access and time needed for independent evaluation of the AI system.","note":"","caveat":"the quote cuts off part of the sentence. Wrong section label (3(d) is 'Protect Privacy'). Quote omits the next sentence letting agencies allow vendors to run the testing instead. Duty is a contract term, binding only via contract."},{"part":"A","supported":"partial","quote":"Contracts must ensure compliance with minimum risk management practices for high-impact use cases as required under M-25-21.","where":"Section 4","specifics":"Contracts for AI must build in compliance with M-25-21 risk practices (testing, impact assessment, monitoring); contract terms also give the agency a right to regularly monitor performance, risks and effectiveness.","note":"Extra tag; A duties themselves live in M-25-21.","caveat":"Wrong section label. Quote only says contracts must ensure M-25-21 compliance; the 'right to regularly monitor' in the specifics is item E, and the A duties live in M-25-21."},{"part":"SCOPE","supported":"yes","quote":"This memorandum shall apply to any contract awarded pursuant to a solicitation issued on or after the date that is 180 days after issuance of this memorandum","where":"Section 2(c) (Future Contracts for AI)","specifics":"Applies to federal AI contracts from solicitations issued 180 days after the memo, plus renewals and extensions after that date.","note":"Section 3(a)(ii) also requires agencies to determine whether a system is likely to host high-impact AI per M-25-21.","caveat":"delayed or expires"}]},"NY|LOADinG Act (S 7543)":{"meta":{"version":"Amended","date":"2023-06-05","textUrl":"https://legiscan.com/NY/text/S07543/id/3006502","stateUrl":"https://assembly.state.ny.us/leg/?default_fld=&bn=S07543&term=2023&Summary=Y&Actions=Y&Text=Y&Committee%26nbspVotes=Y&Floor%26nbspVotes=Y#S07543B","legiscan":"https://legiscan.com/NY/bill/S07543/2023","status":4,"statusDate":"2024-12-21"},"q":[{"part":"I","supported":"partial","quote":"law, shall submit to the legislature a disclosure on the use of such","where":"Section 3 (uncodified disclosure of existing systems)","specifics":"Each state agency using an automated decision-making system must, within one year of the effective date, submit a disclosure (description, software vendors, start date, purpose, impact assessments) to the legislature.","note":"Goes to the legislature, not a public inventory; impact assessments are published on the agency website (Section 404(2)(a)).","caveat":""},{"part":"A","supported":"yes","quote":"(i) accuracy, fairness, bias and discrimination, and an assessment of","where":"Section 403(1)(d)(i)","specifics":"Agencies must conduct and sign an impact assessment (renewed at least every two years and before material changes) that tests for accuracy, fairness and bias.","note":"","caveat":""},{"part":"A","supported":"yes","quote":"produces discriminatory or biased outcomes, the state agency shall cease","where":"Section 403(2)","specifics":"If an impact assessment finds discriminatory or biased outcomes, the agency must stop using the system and any information it produced.","note":"","caveat":""},{"part":"H","supported":"yes","quote":"to continued and operational meaningful human review.","where":"Section 402(1)","specifics":"A state agency (or entity acting for it) may not use an automated decision-making system for public assistance benefits, rights, safety or welfare unless it is subject to continued and operational meaningful human review.","note":"Quote is the closing line of the sentence; sentence starts at Section 402(1) 'No state agency ...'.","caveat":""},{"part":"H","supported":"yes","quote":"No state agency shall authorize any procurement, purchase or acqui-","where":"Section 402(2)","specifics":"Agencies may not authorize procurement of such systems for benefits or rights decisions unless the system is subject to continued and operational meaningful human review.","note":"Also supports V (procurement condition).","caveat":""},{"part":"O","supported":"partial","quote":"assembly at least thirty days prior to the implementation of the auto-","where":"Section 404(1)","specifics":"Each impact assessment goes to the governor, Senate president and Assembly speaker at least 30 days before the system is implemented; there is no oversight commission, enforcement agency or penalty.","note":"Legislative oversight only; no enforcement body. Sentence starts 'Each impact assessment ... shall be submitted to the governor,'.","caveat":""},{"part":"V","supported":"partial","quote":"(b) a list of any software vendors related to such automated deci-","where":"Section 3(b) (uncodified disclosure)","specifics":"The agency's disclosure to the legislature must list related software vendors; no duty is placed on vendors.","note":"Not tagged; weak.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"delivery of any public assistance benefit; (b) will have a material","where":"Section 402(1)(a)-(b)","specifics":"Covers state agencies and entities acting for them that use automated systems in delivering any public assistance benefit or with material impact on rights, civil liberties, safety or welfare.","note":"","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"cash assistance, grants, child care assistance, housing assistance,","where":"Section 401(4) (definition of public assistance benefit)","specifics":"'Public assistance benefit' includes cash assistance, grants, child care, housing, unemployment, transportation and education assistance; federally administered programs are excluded.","note":"Definition begins 'any service or program within the control of the state, or benefit provided by the state ... including but not limited to public assistance,'. State agencies only; legislature and judiciary excluded.","caveat":"a definition, not itself a duty"}]},"NY|S 7599 / A 8295":{"meta":{"version":"Amended","date":"2025-04-23","textUrl":"https://legiscan.com/NY/text/S07599/id/3253749","stateUrl":"https://assembly.state.ny.us/leg/?default_fld=&bn=S07599&term=2025&Summary=Y&Actions=Y&Text=Y&Committee%26nbspVotes=Y&Floor%26nbspVotes=Y#S07599C","legiscan":"https://legiscan.com/NY/bill/S07599/2025","status":4,"statusDate":"2025-12-19"},"q":[{"part":"I","supported":"yes","quote":"publish a list of such automated decision-making tools on such govern-","where":"Section 502 (new State Tech. Law art. 5)","specifics":"Every government agency (state and local) using an automated decision-making tool must publish a list of tools (description, start date, purpose) on its website by Dec. 30 after the effective date, then annually.","note":"Enacted but repealed before effect by S8831.","caveat":"delayed or expires"},{"part":"I","supported":"yes","quote":"state open data website on the thirtieth of December next succeeding the","where":"Section 103-f (new State Tech. Law)","specifics":"The state technology office must keep an inventory of state automated decision-making tools and post it on the NY open data website each year.","note":"Enacted but repealed before effect by S8831.","caveat":"Text says 'the office' (undefined in this bill) not 'state technology office'; inventory can withhold security-sensitive info. Repealed by S 8831."},{"part":"A","supported":"yes","quote":"with this section at least once every two years. An impact assessment","where":"Section 503(1)","specifics":"Government agencies must complete a signed impact assessment, repeat it at least every two years and before material changes.","note":"Repealed by S8831.","caveat":"delayed or expires"},{"part":"A","supported":"yes","quote":"produces discriminatory or biased outcomes, the government agency shall","where":"Section 503(2)","specifics":"If an assessment finds discriminatory or biased outcomes, the agency must cease using the tool and information produced by it.","note":"Repealed by S8831. Bias testing at Section 503(1)(d)(i).","caveat":"delayed or expires"},{"part":"SCOPE","supported":"yes","quote":"(b) a county, city, town or village; (c) a school district,","where":"Section 501(3) (Government agency)","specifics":"Definition of 'government agency' covers the state, counties, cities, towns, villages, school districts, SUNY/CUNY, authorities and other units of government, so local governments are included.","note":"Quote is the middle of a list starting '(a) the state or civil division thereof'.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"that do not materially affect the rights, liberties, benefits, safety or","where":"Section 501(1) (Automated decision-making tool)","specifics":"Tools excluded from coverage are basic computing tools that do not materially affect individuals' rights, liberties, benefits, safety or welfare.","note":"","caveat":"a definition, not itself a duty"},{"part":"REPEAL","supported":"yes","quote":"Article 5 of the state technology law, as added by a chap-","where":"S8831 Section 1","specifics":"S 8831 (Chapter 86 of 2026) repeals Article 5 (agency tool lists and impact assessments) as added by S7599-C.","note":"Repeal language in NY_S8831.txt.","caveat":"Located in NY_S8831.txt, which is the introduced bill (8 Jan 2026); enactment and 'Chapter 86 of 2026' are not shown in the text."},{"part":"REPEAL","supported":"yes","quote":"Section 103-f of the state technology law, as added by a chapter","where":"S8831 Section 2","specifics":"S 8831 also repeals the state tool inventory (section 103-f) as added by S7599-C.","note":"Repeal language in NY_S8831.txt.","caveat":"Same as #9; chapter number and enactment not verifiable from the text."},{"part":"REPEAL","supported":"yes","quote":"To the extent feasible, any covered entity that","where":"S8831 Section 6 (new State Tech. Law section 402-a)","specifics":"What survives: counties, cities, towns, villages, school districts, SUNY, CUNY and community colleges must publish a list of automated EMPLOYMENT decision-making tools only.","note":"Quote is from the first line of 402-a; sentence continues 'utilizes an automated employment decision-making tool, shall publish a list'.","caveat":"limited by conditions or exceptions; the quote cuts off part of the sentence. Opens 'To the extent feasible', so the duty is qualified; specifics says 'must publish' without that. Employment-tool list is only the surviving list duty; S 8831 also keeps AI-employee protections and Sec 402 for state agencies."}]},"MD|SB 818 (AI Governance Act)":{"meta":{"version":"Chaptered","date":"2024-05-15","textUrl":"https://legiscan.com/MD/text/SB818/id/2998150","stateUrl":"https://mgaleg.maryland.gov/2024RS/Chapters_noln/CH_496_sb0818e.pdf","legiscan":"https://legiscan.com/MD/bill/SB818/2024","status":4,"statusDate":"2024-05-09"},"q":[{"part":"I","supported":"yes","quote":"THE DEPARTMENT SHALL MAKE EACH INVENTORY REQUIRED BY THIS SECTION AN AGGREGATED STATEWIDE INVENTORY PUBLICLY AVAILABLE ON ITS WEBSITE.","where":"§ 3.5–803(c) (shown as (C) in the chapter text)","specifics":"The Department of Information Technology must publish a statewide inventory of the AI systems each state unit reports (name, vendor, capabilities, purpose, whether assessed), withholding security-sensitive information.","note":"Chaptered text mixes struck and new words; this sentence reads cleanly.","caveat":"limited by conditions or exceptions. Inventory covers only rights-impacting or safety-impacting high-risk AI (not 'each AI system'); 803(d) bars posting security-sensitive items. Sentence reads cleanly."},{"part":"A","supported":"yes","quote":"A UNIT OF STATE GOVERNMENT THAT EMPLOYS RIGHTS–IMPACTING OR SAFETY–IMPACTING HIGH–RISK ARTIFICIAL INTELLIGENCE SHALL CONDUCT","where":"§ 3.5–805(b) (printed as 3.5–804 (B) with renumbering)","specifics":"A state unit using rights-impacting or safety-impacting AI must conduct regular impact assessments on a schedule set by the Governor's AI Subcabinet; units must also assess systems procured on/after the cutoff date and older systems by a later deadline (§ 3.5–803(e)).","note":"Quote ends mid-sentence ('REGULAR IMPACT ASSESSMENTS, AS DETERMINED BY THE ... SUBCABINET') because a page break follows. Dates in 3.5-803(e) are mixed with struck text.","caveat":"the quote cuts off part of the sentence. Quote ends mid-sentence ('SHALL CONDUCT'); schedule words come from the next line. Dates in 3.5-803(e) are mixed with struck words (reads as Dec 31, 2026 / Feb 1, 2026 / July 1, 2027 at best)."},{"part":"V","supported":"partial","quote":"(2) THE VENDOR THAT PROVIDED THE SYSTEM, IF APPLICABLE;","where":"§ 3.5–803(b)(2)","specifics":"Each state unit's AI inventory entry must name the vendor that provided the system; no duty is placed on vendors themselves.","note":"Weak V: vendor is only identified, no vendor documentation or cooperation duty found.","caveat":""},{"part":"O","supported":"yes","quote":"(A) THERE IS A GOVERNOR'S ARTIFICIAL INTELLIGENCE SUBCABINET OF THE GOVERNOR'S EXECUTIVE COUNCIL.","where":"§ 3.5–806(a) (printed as 3.5–805 with renumbering)","specifics":"Creates the Governor's AI Subcabinet, chaired by the Secretary of IT, which oversees the state's AI inventory, impact assessments and monitoring of rights/safety-impacting AI.","note":"Subcabinet duties at § 3.5–806(e). No enforcement penalties or private right of action found.","caveat":""},{"part":"O","supported":"yes","quote":"(E) THE SUBCABINET SHALL: (1) DEVELOP STRATEGY, POLICY, AND MONITORING PROCESSES FOR RESPONSIBLE AND PRODUCTIVE USE OF ARTIFICIAL INTELLIGENCE AND ASSOCIATED DATA BY UNITS OF STATE GOVERNMENT;","where":"§ 3.5–806(e)(1)","specifics":"The Subcabinet must develop strategy, policy and monitoring processes for state AI use and oversee the AI inventory and impact assessments.","note":"","caveat":"Sub-items of (e)(2) mix struck and new words (duplicate (III)/(IV)); which oversight items survive is not certain."},{"part":"SCOPE","supported":"yes","quote":"ACCESS TO CRITICAL RESOURCES OR SERVICES, INCLUDING HEALTH CARE, FINANCIAL SERVICES, SOCIAL SERVICES, TRANSPORTATION, NONDECEPTIVE INFORMATION ABOUT GOODS AND SERVICES, AND GOVERNMENT BENEFITS OR PRIVILEGES.","where":"§ 3.5–801 (definition of rights-impacting AI), item (3)","specifics":"AI that is a basis for decisions with legal, material or similarly significant effect on access to social services or government benefits counts as rights-impacting AI and is subject to the inventory and assessments.","note":"Chaptered text; the words after 'PRIVILEGES.' are struck.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"EACH UNIT OF STATE GOVERNMENT SHALL: (1) CONDUCT AN INVENTORY OF SYSTEMS THAT EMPLOY RIGHTS–IMPACTING OR SAFETY–IMPACTING HIGH–RISK ARTIFICIAL INTELLIGENCE;","where":"§ 3.5–803(a)(1)","specifics":"Applies to each unit of state government (state agencies, with higher-ed partnerships also covered); local governments are not named.","note":"Opening words of (a) read 'ON OR BEFORE DECEMBER 1, 2025, AND REGULARLY THEREAFTER,'.","caveat":"limited by conditions or exceptions. Dates mixed with struck text. Specifics omits that AG, Comptroller and Treasurer are outside the subtitle (they only adopt compatible policies); higher-ed coverage is limited (research-only AI excluded)."},{"part":"N","supported":"no","quote":"","where":"§ 3.5–804","specifics":"An older draft (struck) required notifying negatively impacted individuals and guidance on opting out, but the surviving text has no notice or human-review duty; only the preamble (WHEREAS clauses) mentions notice and human alternatives.","note":"Not tagged; reported as absent."}]},"CO|SB 26-189":{"meta":{"version":"Chaptered","date":"","textUrl":"https://legiscan.com/CO/text/SB189/id/3436600","stateUrl":"https://leg.colorado.gov/bill_files/116489/download","legiscan":"https://legiscan.com/CO/bill/SB189/2026","status":4,"statusDate":"2026-05-14"},"q":[{"part":"N","supported":"yes","quote":"(1) PRIOR TO A DEPLOYER USING A COVERED ADMT TO MATERIALLY INFLUENCE A CONSEQUENTIAL DECISION, THE DEPLOYER SHALL PROVIDE A CLEAR AND CONSPICUOUS NOTICE TO A CONSUMER THAT THE DEPLOYER USED OR WILL USE A COVERED ADMT","where":"§ 6-1-1704(1)","specifics":"Before using covered automated decision-making technology in a consequential decision, the deployer must give the consumer clear, conspicuous notice (a prominent public posting at the point of interaction satisfies this under subsection (2)).","note":"Sentence continues 'IN A CONSEQUENTIAL DECISION AFFECTING THE CONSUMER ...'.","caveat":"limited by conditions or exceptions; delayed or expires"},{"part":"N","supported":"yes","quote":"(3) IF A DEPLOYER USES A COVERED ADMT TO MATERIALLY INFLUENCE A CONSEQUENTIAL DECISION THAT RESULTS IN AN ADVERSE OUTCOME FOR A CONSUMER, THE DEPLOYER SHALL PROVIDE WITHIN THIRTY DAYS AFTER MAKING THE DECISION:","where":"§ 6-1-1704(3)","specifics":"After an adverse outcome, within 30 days the deployer must give a plain-language description of the decision and the ADMT's role, how to request more information, and an explanation of consumer rights.","note":"List items (a)-(c) follow the colon.","caveat":"limited by conditions or exceptions; delayed or expires"},{"part":"H","supported":"yes","quote":"(II) AN OPPORTUNITY FOR MEANINGFUL HUMAN REVIEW AND RECONSIDERATION OF THE CONSEQUENTIAL DECISION, TO THE EXTENT COMMERCIALLY REASONABLE.","where":"§ 6-1-1705(1)(a)(II)","specifics":"After an adverse outcome, a consumer may request, and the deployer must provide, correction of inaccurate personal data and a chance for meaningful human review and reconsideration, to the extent commercially reasonable.","note":"'Commercially reasonable' is a qualifier; Section 6-1-1701(15) defines meaningful human review.","caveat":"limited by conditions or exceptions; permissive (\"may\"), not mandatory. Consumer must request; review only 'to the extent commercially reasonable'. Item (I) is instructions for requesting and correcting data, not a duty to correct (and 1705(1)(c) excludes opinions/scores); specifics overstates."},{"part":"V","supported":"yes","quote":"A DEVELOPER SHALL MAKE AVAILABLE TO EACH DEPLOYER OF A COVERED ADMT DEVELOPED BY THE DEVELOPER, IN A FORM AND MANNER THAT IS REASONABLY UNDERSTANDABLE TO A DEPLOYER AND THAT PROTECTS TRADE SECRETS OR INFORMATION PROTECTED FROM DISCLOSURE BY STATE OR FEDERAL LAW:","where":"§ 6-1-1702(1)","specifics":"From Jan. 1, 2027, developers must give each deployer documentation of intended and harmful uses, training-data categories, known limitations, instructions for use, monitoring and human review, and information needed for the deployer's notices.","note":"Developer must also notify deployers of material updates (§ 6-1-1702(2)).","caveat":"limited by conditions or exceptions; delayed or expires"},{"part":"O","supported":"yes","quote":"(1) (a) THE ATTORNEY GENERAL SHALL ENFORCE THIS PART 17 THROUGH THE \"COLORADO CONSUMER PROTECTION ACT\", THIS ARTICLE 1.","where":"§ 6-1-1706(1)(a)","specifics":"The Attorney General enforces the law as a deceptive trade practice, with exclusive enforcement of the disclosure and consumer-rights sections.","note":"Cure period: see next entry.","caveat":""},{"part":"O","supported":"yes","quote":"(b) IF THE DEVELOPER OR DEPLOYER FAILS TO CURE A VIOLATION WITHIN SIXTY DAYS AFTER RECEIPT OF A NOTICE OF VIOLATION, THE ATTORNEY GENERAL MAY BRING AN ACTION PURSUANT TO THIS SECTION.","where":"§ 6-1-1706(3)(b)","specifics":"Before enforcement the AG must issue a notice of violation if a cure is possible; the violator has 60 days to cure.","note":"Knowing violations may skip the cure period (§ 6-1-1706(3)(c)).","caveat":"limited by conditions or exceptions; delayed or expires. Cure is only if AG deems cure possible; skipped for knowing or repeated violations; and 1706(3)(f) repeals subsection (3) effective Jan 1, 2030. Specifics omits the 2030 sunset."},{"part":"O","supported":"yes","quote":"NOTHING IN THIS PART 17 CREATES A NEW PRIVATE RIGHT OF ACTION.","where":"§ 6-1-1709(1)","specifics":"No private right of action is created.","note":"","caveat":""},{"part":"A","supported":"no","quote":"","where":"Section 1 (repeal and reenact of Part 17)","specifics":"The reenacted Part 17 has no impact assessment, pre-use testing, bias testing or discontinuation duty (the 2024 AI Act had risk-management and impact-assessment duties); the only monitoring is developer instructions for deployer monitoring in 6-1-1702(1)(d).","note":"Tag A0 (rolled back) is confirmed: text omits it. Part 17 is repealed and reenacted per the quoted opening of Section 1: 'SECTION 1. In Colorado Revised Statutes, repeal and reenact, with amendments, part 17 of article 1 of title 6'."},{"part":"A","supported":"no","quote":"SECTION 1. In Colorado Revised Statutes, repeal and reenact, with amendments, part 17 of article 1 of title 6 as follows:","where":"Section 1","specifics":"The prior Part 17 (2024 AI Act) is repealed and replaced; the replacement contains no impact-assessment, bias-testing or discontinuation duty.","note":"Evidence of rollback of A.","caveat":"Quote shows only repeal-and-reenact. The file contains no impact-assessment, testing or discontinuation duty (verified by search), but that the old law had them is external knowledge. The 2024 act also was delayed and never took effect (external)."},{"part":"SCOPE","supported":"yes","quote":"(7) \"DEPLOYER\" MEANS A PERSON DOING BUSINESS IN COLORADO THAT DEPLOYS A COVERED ADMT.","where":"§ 6-1-1701(7)","specifics":"A deployer is any 'person doing business in Colorado' that deploys covered ADMT; the text neither names nor exempts state or local government agencies.","note":"OPEN QUESTION: in this file there is no definition of 'person' and no express exemption or inclusion of state agencies, municipalities or other governmental bodies; coverage of governments turns on whether 'person doing business in Colorado' reaches public bodies (definition of 'person' in C.R.S. 6-1-102 is not in the bill).","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"(g) ESSENTIAL GOVERNMENT SERVICES AND PUBLIC BENEFITS, INCLUDING ELIGIBILITY AND RENEWAL DETERMINATIONS.","where":"§ 6-1-1701(6)(g) (covered domain)","specifics":"One of the seven covered domains is essential government services and public benefits, including eligibility and renewal determinations.","note":"Naming government services as a domain suggests decisions by government actors are contemplated, but 'deployer' is still 'a person doing business in Colorado'.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"A DECISION, DETERMINATION, OR ACTION MADE ABOUT A CONSUMER THAT RELATES TO THE PROVISION OF OR A CONSUMER'S ACCESS TO, ELIGIBILITY FOR, SELECTION FOR, OR COMPENSATION FOR A COVERED DOMAIN;","where":"§ 6-1-1701(3)(a)(I)","specifics":"A consequential decision is one about a consumer relating to provision of, access to or eligibility for a covered domain, including government services and benefits.","note":"No exemption for government found in the consequential-decision exclusions (3)(b).","caveat":"a definition, not itself a duty; limited by conditions or exceptions"}]},"OH|SB 315":{"meta":{"version":"Enrolled","date":"","textUrl":"https://legiscan.com/OH/text/SB315/id/3447946","stateUrl":"https://search-prod.lis.state.oh.us/api/v2/general_assembly_136/legislation/sb315/05_EN/pdf/","legiscan":"https://legiscan.com/OH/bill/SB315/2025","status":4,"statusDate":"2026-10-06"},"q":[{"part":"H","supported":"yes","quote":"(1) No action shall be taken automatically without human review as a result of the automated review tool's determination or decision. (2) The appropriate department employee responsible for overseeing the determination or decision shall review the findings of the automated review tool to confirm the tool made the correct determination or decision.","where":"Sec. 5162.90(B)(1)-(2) (parallel text in Sec. 5164.11(B))","specifics":"When the Department of Medicaid uses automated review tools (including AI and fraud detection) for the listed program-integrity provisions, no action may be taken automatically; a department employee must review the findings and confirm the tool's determination.","note":"Limited to actions under the listed sections (5162.17-5162.19; 5164.292 etc.); not a general appeal right for applicants.","caveat":"limited by conditions or exceptions. Text is accurate and appears in both 5162.90(B) and 5164.11(B), but it is limited to listed provider/program-integrity sections (not eligibility or benefit decisions for recipients); rating H2 overstates that narrowness."},{"part":"O","supported":"partial","quote":"the department shall handle the credible allegation in accordance with that section and refer the credible allegation to the attorney general for investigation.","where":"Sec. 5164.404(C)","specifics":"Where audits of Medicaid fraud-detection tools produce a credible allegation of fraud, the department must refer it to the Attorney General; sub. (B) requires the department to run periodic audits and investigations on data from EVV and fraud-detection tools.","note":"Enforcement here is about provider fraud, not oversight of the AI tools themselves; no AI oversight body, so only partial.","caveat":"Quote is about referring a fraud allegation to the AG after a Medicaid audit; it is not oversight or enforcement of AI tools. Sub (B) audits cover data collected through EVV and fraud-detection tools, which is ambiguous as to 'audits of the tools'."},{"part":"SCOPE","supported":"yes","quote":"(B) When implementing sections 5162.17 to 5162.19 of the Revised Code, if the department of medicaid uses any automated review tools, all of the following shall occur:","where":"Sec. 5162.90(B)","specifics":"The human-review rule applies only to the Ohio Department of Medicaid and only to its program-integrity sections (EVV dashboard, claims checks, third-party liability).","note":"Parallel Sec. 5164.11(B) lists sections 5164.292, 5164.40-5164.407 and others.","caveat":"limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"(2) \"Automated review tools\" mean artificial intelligence, automated fraud detection tools, automated algorithmic analysis, or any other electronic automated review tool, system, or service.","where":"Sec. 5164.11(A)(2)","specifics":"Defines the tools covered: AI, automated fraud detection and algorithmic analysis used by the Medicaid department.","note":"Text covers Medicaid only; SNAP provisions concern chip-enabled EBT cards and cybersecurity, not automated decision tools.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"The department of medicaid shall develop and implement automated fraud-detection tools to assist with identifying fraud through the use of the electronic verification systems","where":"Sec. 5164.404(A)","specifics":"Directs the Medicaid department to build automated fraud-detection tools that flag irregular provider activity in electronic visit verification data.","note":"Targets providers, not recipients.","caveat":""}]},"TX|HB 149 (TRAIGA)":{"meta":{"version":"","date":"","textUrl":"","stateUrl":"","legiscan":"https://legiscan.com/TX/bill/HB149/2025","status":4,"statusDate":"2025-06-22"},"q":[{"part":"N","supported":"partial","quote":"shall disclose to each consumer, before or at the time of","where":"Sec. 552.051(b)","specifics":"A governmental agency making available an AI system intended to interact with consumers must disclose, clearly and in plain language, before or at the time of interaction that the consumer is interacting with AI (even if obvious, per (c)).","note":"Applies to consumer-facing interaction (e.g., chatbots), not to explanations of adverse decisions. Sentence starts 'A governmental agency that makes available an artificial intelligence system intended to interact with consumers'.","caveat":"limited by conditions or exceptions; delayed or expires. Duty is real but limited to AI 'intended to interact with consumers' (consumer = Texas resident acting individually); the section uses undefined 'governmental agency'. Sec. 9 excuses state agencies from mandatory duties unless money is appropriated; effective Jan 1, 2026. Supports only a loose N."},{"part":"O","supported":"yes","quote":"general has exclusive authority to enforce this chapter, except to","where":"Sec. 552.101(a)","specifics":"The Attorney General has exclusive enforcement authority; there is no private right of action under (b).","note":"Sentence begins 'The attorney general has exclusive authority'.","caveat":""},{"part":"O","supported":"yes","quote":"before the 60th day after the date the attorney","where":"Sec. 552.104(b)(1)","specifics":"The AG must give notice of violation and may not sue until 60 days have passed (or earlier if the violation is cured and certified).","note":"Sentence continues 'general provides the notice under Subsection (a)'.","caveat":"limited by conditions or exceptions"},{"part":"O","supported":"yes","quote":"uncurable, not less than $80,000 and not more than $200,000; and","where":"Sec. 552.105(a)(2)","specifics":"Civil penalties: $10,000-$12,000 per curable violation, $80,000-$200,000 per uncurable violation, and $2,000-$40,000 per day for continuing violations.","note":"","caveat":"limited by conditions or exceptions"},{"part":"O","supported":"yes","quote":"state are ethical and developed in the public's best interest;","where":"Sec. 554.001(a)(1)","specifics":"Creates the Texas Artificial Intelligence Council to ensure AI is ethical and not harmful, train state agencies and local governments, and issue reports; it cannot make binding rules (Sec. 554.103).","note":"Sandbox program (Chapter 553) is separate.","caveat":""},{"part":"I","supported":"partial","quote":"an evaluation of the use or considered use of","where":"Sec. 2054.068(b)(5), Gov't Code (SECTION 6 of the act)","specifics":"The Department of Information Resources collects from each state agency an evaluation of its use or considered use of AI systems; SECTION 7 adds an inventory of AI systems to each agency's information resources review.","note":"Not tagged. Reported to DIR, not published as a public inventory.","caveat":"limited by conditions or exceptions. The quoted (b)(5) is only an 'evaluation of the use or considered use' collected by DIR; the actual inventory is in SECTION 7 (2054.0965(b)(2)), which the specifics mention but the quote does not show. Not public. Sec. 9 appropriation condition applies."},{"part":"SCOPE","supported":"yes","quote":"of this state or of any political subdivision of this state, that","where":"Sec. 552.001(3) (governmental entity)","specifics":"'Governmental entity' covers state bodies and political subdivisions exercising governmental functions, except hospital districts and higher-ed institutions.","note":"Sentence: 'Governmental entity means any department, commission, board, office, authority, or other administrative unit of this state or of any political subdivision of this state, that exercises governmental functions'.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"not use or deploy an artificial intelligence system that evaluates","where":"Sec. 552.053","specifics":"A governmental entity may not use AI to score people on social behavior or personal characteristics where it causes unrelated or disproportionate detrimental treatment or infringes a right.","note":"No benefits/Medicaid/SNAP language in the text; no impact assessment, human review or vendor duty.","caveat":""}]},"TX|SB 1964":{"meta":{"version":"Enrolled","date":"2025-06-03","textUrl":"https://legiscan.com/TX/text/SB1964/id/3250757","stateUrl":"https://capitol.texas.gov/tlodocs/89R/billtext/html/SB01964F.htm","legiscan":"https://legiscan.com/TX/bill/SB1964/2025","status":4,"statusDate":"2025-06-20"},"q":[{"part":"I","supported":"partial","quote":"an inventory and identification of the artificial intelligence systems and heightened scrutiny artificial intelligence systems deployed by the agency, including an evaluation of the purpose of and risk mitigation measures for each system","where":"Sec. 2054.0965(b)(6), Gov't Code (SECTION 3)","specifics":"State agencies' information resources review must include an inventory of AI systems and heightened-scrutiny AI systems with purpose and risk mitigation; Section 2054.068(b)(2) has the Department of Information Resources collect AI inventories.","note":"The text does not say the inventory is posted publicly or on the open data portal (Sec. 2054.137(c) concerns three high-value data sets); local governments only complete reviews of heightened-scrutiny AI and provide them on request (Sec. 2054.0965(c)).","caveat":"limited by conditions or exceptions. Quote shows an inventory in the agency review, but nothing in the text publishes it; the description's claim of posting on the open data portal is not supported (2054.137(c) concerns three high-value data sets)."},{"part":"A","supported":"yes","quote":"A state agency that deploys or uses a heightened scrutiny artificial intelligence system or a vendor that contracts with a state agency for the deployment or use of a heightened scrutiny artificial intelligence system shall conduct a system assessment that outlines: (1) risks of unlawful harm; (2) system limitations; and (3) information governance practices.","where":"Sec. 2054.708(a)","specifics":"State agencies or their vendors using heightened-scrutiny AI must conduct a system assessment of unlawful-harm risk, limitations and information governance; copy to DIR on request; assessments are confidential.","note":"Upgrade A from 1 to 2: this is a binding assessment duty, not just standards.","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"yes","quote":"require the assessment and documentation of the heightened scrutiny artificial intelligence system's known security risks, performance metrics, and transparency measures: (A) before deploying the system;","where":"Sec. 2054.703(b)(2)","specifics":"DIR's minimum standards must require pre-deployment assessment and documentation (and again after material changes) of security risks, performance and transparency.","note":"","caveat":"delayed or expires"},{"part":"N","supported":"yes","quote":"Each state agency and local government deploying or using an artificial intelligence system that is public-facing or that is a controlling factor in a consequential decision shall include a standardized notice on all related applications, Internet websites, and public computer systems.","where":"Sec. 2054.711(a)","specifics":"Agencies and local governments must post a standardized notice (using a DIR form) about AI that is public-facing or a controlling factor in a consequential decision.","note":"Notice is general, not an individual explanation of an adverse decision. Not tagged.","caveat":"limited by conditions or exceptions"},{"part":"N","supported":"yes","quote":"A state agency that procures, develops, deploys, or uses a public-facing artificial intelligence system shall provide clear disclosure of interaction with the system to the public","where":"Sec. 2054.707","specifics":"State agencies must disclose to the public when they interact with a public-facing AI system, unless a reasonable person would already know.","note":"Not tagged.","caveat":"limited by conditions or exceptions"},{"part":"H","supported":"partial","quote":"The guidance must address: (1) human oversight and control; (2) fairness and accuracy; (3) transparency, including consumer disclosures; (4) data privacy and security; (5) public and internal redress, including accountability and liability; and (6) the frequency of evaluations and documentation of improvements.","where":"Sec. 2054.702(b)","specifics":"DIR's AI code of ethics, which state agencies and local governments must adopt, must address human oversight and control and redress, but the bill itself imposes no specific human-review or appeal right.","note":"Not tagged; indirect only.","caveat":""},{"part":"V","supported":"yes","quote":"mitigating the risk of unlawful harm by contractually requiring vendors to implement risk management frameworks when deploying heightened scrutiny artificial intelligence systems on behalf of state agencies or local governments.","where":"Sec. 2054.703(b)(4)(B)","specifics":"DIR's standards must include guidelines for contractually requiring vendors to implement risk management frameworks; vendors must also do the Sec. 2054.708 assessment and face notice, cure within 31 days, and contract voiding under Sec. 2054.709.","note":"Not tagged.","caveat":"limited by conditions or exceptions. Quote only covers DIR guidelines. The binding vendor duty is the 2054.708(a) system assessment. 'cure within 31 days' in specifics: text says 'before the 31st day' (i.e. 30 days)."},{"part":"V","supported":"yes","quote":"If the vendor fails to cure the violation before the 31st day after the date the vendor receives the notice of intent to void the contract under Subsection (d), the state agency may void the contract without further obligation to the vendor.","where":"Sec. 2054.709(e)","specifics":"After AG notice and a 31-day cure, a state agency may void the contract of a vendor that violated the subchapter; repeat offenders can be barred by the comptroller.","note":"","caveat":"Text says cure 'before the 31st day', not 31 days; and the sequence is two steps (AG notice, then agency notice of intent), each with this window. Comptroller bar is subsection (f) and not in the quote."},{"part":"O","supported":"yes","quote":"The attorney general shall: (1) review a report submitted under this section or a complaint reported through the web page established under Section 2054.710; and (2) determine whether to bring an action to enjoin a violation of this subchapter.","where":"Sec. 2054.709(b)","specifics":"The Attorney General reviews violation reports and complaints and decides whether to sue for an injunction; DIR writes rules and a public sector AI advisory board assists agencies (Sec. 2054.705). No monetary penalty or private right of action.","note":"","caveat":"permissive (\"may\"), not mandatory"},{"part":"SCOPE","supported":"yes","quote":"\"Consequential decision\" means a decision that has a material legal or similarly significant effect on the provision, denial, or conditions of a person's access to a government service.","where":"Sec. 2054.003(2-b) (SECTION 1)","specifics":"Covers state agency AI used in decisions about access to government services; benefits, Medicaid and SNAP are not named.","note":"","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"State agencies and local governments shall adopt the standards developed under Subsection (a).","where":"Sec. 2054.703(c)","specifics":"The minimum risk standards for heightened-scrutiny AI bind both state agencies and local governments.","note":"","caveat":""}]},"CT|PA 23-16 (SB 1103)":{"meta":{"version":"Chaptered","date":"2023-06-05","textUrl":"https://legiscan.com/CT/text/SB01103/id/2823778","stateUrl":"https://www.cga.ct.gov/2023/ACT/PA/PDF/2023PA-00016-R00SB-01103-PA.PDF","legiscan":"https://legiscan.com/CT/bill/SB01103/2023","status":4,"statusDate":"2023-06-07"},"q":[{"part":"I","supported":"yes","quote":"Not later than December 31, 2023, and annually thereafter, the Department of Administrative Services shall conduct an inventory of all systems that em ploy artificial intelligence and are in use by any state agency.","where":"Sec. 1(b)(1)","specifics":"DAS must inventory all AI systems in use by state agencies every year starting Dec. 31, 2023, listing name, vendor, uses, whether it informs decisions, and whether an impact assessment was done.","note":"","caveat":""},{"part":"I","supported":"yes","quote":"The Department of Administrative Services shall make each inventory conducted pursuant to subdivision (1) of this subsection publicly available on the state's open data portal.","where":"Sec. 1(b)(2)","specifics":"The inventory must be posted publicly on the state open data portal.","note":"","caveat":""},{"part":"A","supported":"yes","quote":"no state agency shall implement any system that employs artificial intelligence (1) unless the state agency has performed an impact assessment, in accordance with the policies and procedures established pursuant to subsection (b) of this section","where":"Sec. 2(c)","specifics":"From Feb. 1, 2024 an agency may not implement an AI system without first doing an impact assessment for unlawful discrimination or disparate impact, and may not implement one the agency head finds will discriminate.","note":"","caveat":""},{"part":"A","supported":"yes","quote":"Beginning on February 1, 2024, the Department of Administrative Services shall perform ongoing assessments of systems that employ artificial intelligence and are in use by state agencies","where":"Sec. 1(c)","specifics":"DAS must run ongoing assessments of agency AI systems to ensure no unlawful discrimination or disparate impact.","note":"","caveat":""},{"part":"O","supported":"partial","quote":"Not later than February 1, 2024, the Office of Policy and Management shall develop and establish policies and procedures concerning the development, procurement, implementation, utilization and ongoing assessment of systems that employ artificial intelligence","where":"Sec. 2(b)(1)","specifics":"OPM sets binding policies and DAS does ongoing assessments; there is also a temporary study working group (Sec. 5) but no enforcement, penalty, or AG role.","note":"Oversight is by executive agencies (OPM/DAS), not an independent body; no enforcement mechanism.","caveat":"Quote shows OPM policy-setting by an executive agency; no independent oversight body or enforcement. Only the temporary Sec. 5 working group is advisory."},{"part":"V","supported":"partial","quote":"The name of such system and the vendor, if any, that provided such system;","where":"Sec. 1(b)(1)(A)","specifics":"Inventory must name the vendor; no duty is placed on vendors themselves.","note":"Extra tag; weak. OPM policies must govern procurement (Sec. 2(b)(1)(A)).","caveat":"Only an inventory data field naming the vendor; no vendor duty. Agency procurement policies (Sec. 2(b)(1)(A)) only touch procurement."},{"part":"SCOPE","supported":"yes","quote":"(C) Whether such system was used to independently make, inform or materially support a conclusion, decision or judgment; and","where":"Sec. 1(b)(1)(C)","specifics":"Scope is all AI systems used by any state agency (and separately the Judicial Department), whether or not they decide; benefits and eligibility are not named.","note":"No mention of benefits, Medicaid, SNAP, eligibility or public assistance.","caveat":"Quote is an inventory field, not a scope clause; scope sits in Sec. 1(b)(1) first sentence (all AI systems in use by any state agency). No benefits wording anywhere in text."},{"part":"SCOPE","supported":"yes","quote":"(2) \"State agency\" has the same meaning as provided in section 4d -1 of the general statutes.","where":"Sec. 1(a)(2)","specifics":"Covers state agencies as defined in Conn. Gen. Stat. 4d-1.","note":"","caveat":"a definition, not itself a duty"}]},"CT|PA 26-15 (SB 5)":{"meta":{"version":"Chaptered","date":"2026-05-11","textUrl":"https://legiscan.com/CT/text/SB00005/id/3434382","stateUrl":"https://www.cga.ct.gov/2026/ACT/PA/PDF/2026PA-00015-R00SB-00005-PA.PDF","legiscan":"https://legiscan.com/CT/bill/SB00005/2026","status":4,"statusDate":"2026-05-27"},"q":[{"part":"I","supported":"yes","quote":"(2) The Department of Administrative Services shall make each inventory conducted pursuant to subdivision (1) of this subsection publicly available on the state's open data portal.","where":"Sec. 37(b)(2)","specifics":"DAS must annually inventory AI systems in use by state agencies (new fields: date of last impact assessment, access to personal information, known risks) and post it publicly on the open data portal.","note":"","caveat":"delayed or expires"},{"part":"I","supported":"yes","quote":"(E) The date of the last impact assessment; (F) Whether such system has access to personally identifiable information of individuals in the state; and (G) The known risks of such system toward individuals in the state, communities and state employees.","where":"Sec. 37(b)(1)(E)-(G)","specifics":"Inventory entries must now include date of last impact assessment, PII access, and known risks.","note":"","caveat":"limited by conditions or exceptions. Fields (A)-(G) apply only 'to the extent practicable based on available data' (Sec. 37(b)(1)); the quote omits that qualifier."},{"part":"A","supported":"yes","quote":"the state agency shall complete an artificial intelligence impact assessment in compliance with policies and standards established by the Office of Policy and Management and the Department of Administrative Services.","where":"Sec. 38(b)(3)","specifics":"An agency authorized to procure or acquire AI technology must complete an AI impact assessment under OPM/DAS standards.","note":"","caveat":""},{"part":"A","supported":"yes","quote":"shall be submitted to the Commissioner of Administrative Services, in a form and manner prescribed by the commissioner, and posted on the agency's Internet web site not later than sixty days prior to deployment of such artificial intelligence technology.","where":"Sec. 38(c)","specifics":"Impact assessments go to the DAS Commissioner and must be posted on the agency website at least 60 days before deployment; PII may be redacted.","note":"","caveat":""},{"part":"V","supported":"partial","quote":"No state agency shall authorize any procurement, purchase or acquisition of any artificial intelligence technology, except where the use of such system is in compliance with policies and standards established by the Office of Policy and Management and the Department of Administrative Services.","where":"Sec. 38(b)(2)","specifics":"Procurement of AI is conditioned on compliance with OPM/DAS policies and standards (a procurement condition on agencies, not duties on vendors).","note":"Applies to agencies; no vendor documentation or cooperation duty found. Inventory also lists vendor name.","caveat":"Condition on agencies' procurement, not a duty on vendors; no vendor documentation duty found. V1 rests on weak basis (procurement touch / vendor named in inventory)."},{"part":"O","supported":"partial","quote":"unless such utilization or application is in compliance with policies and standards established by the Office of Policy and Management and the Department of Administrative Services.","where":"Sec. 38(b)(1)","specifics":"OPM and DAS set the policies and standards agencies must follow for AI used in public assistance or with material impact on rights; DAS runs ongoing assessments (Sec. 37(c)).","note":"Central executive oversight only; the AG enforcement language elsewhere in SB 5 relates to the chatbot/social media parts, not state agency use. No penalties for agencies found.","caveat":"limited by conditions or exceptions. Quote is an OPM/DAS standards clause (compliance condition); no enforcement authority or penalties."},{"part":"SCOPE","supported":"yes","quote":"No state agency, or any entity acting on behalf of a state agency, shall, directly or indirectly, utilize or apply any artificial intelligence technology in performing any function that (A) is related to the delivery of any public assistance benefi t to individuals in the state by such agency","where":"Sec. 38(b)(1)","specifics":"Names public assistance benefit delivery and anything with material impact on rights, civil liberties, safety or welfare; also covers entities acting on behalf of an agency.","note":"","caveat":"limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"(B) will have a material impact on the rights, civil liberties, safety or welfare of individuals in the state, unless such utilization or application is in compliance with policies and standards","where":"Sec. 38(b)(1)(B)","specifics":"Covers any AI use with material impact on rights, civil liberties, safety or welfare.","note":"","caveat":"limited by conditions or exceptions"},{"part":"N","supported":"no","quote":"","where":"","specifics":"No notice, explanation or disclosure duty to affected individuals found in the state-agency sections (Sec. 37-38); only public posting of impact assessments.","note":"Chatbot disclosure duties elsewhere in SB 5 are private-sector."},{"part":"H","supported":"no","quote":"","where":"","specifics":"No human review duty for agency AI decisions found in Sec. 37-38.","note":""}]},"VT|H 410 (Act 132)":{"meta":{"version":"Chaptered","date":"2022-05-27","textUrl":"https://legiscan.com/VT/text/H0410/id/2590823","stateUrl":"https://legislature.vermont.gov/Documents/2022/Docs/ACTS/ACT132/ACT132%20As%20Enacted.pdf","legiscan":"https://legiscan.com/VT/bill/H0410/2021","status":4,"statusDate":"2022-05-12"},"q":[{"part":"I","supported":"yes","quote":"The Agency of Digital Services shall conduct a review and make an inventory of all automated decision systems that are being developed, employed, or procured by State government.","where":"3 V.S.A. 3305(b) (Sec. 3)","specifics":"ADS must inventory all ADS developed, used or procured by state government, including name, vendor, capabilities, bias testing status, purpose and fiscal impact; annual update goes in the report to the General Assembly.","note":"No explicit requirement to publish it publicly; it is reported to the legislature (Sec. 2, 3303(a)(8); Sec. 4).","caveat":""},{"part":"I","supported":"yes","quote":"(8)  an annual update to the inventory required by section 3305 of this title.","where":"Sec. 2, 3 V.S.A. 3303(a)(8)","specifics":"The inventory is updated annually in the Secretary's annual report to the General Assembly.","note":"","caveat":""},{"part":"A","supported":"partial","quote":"(4)  whether the automated decision system has been tested for bias by an independent third party, has a known bias, or is untested for bias;","where":"3 V.S.A. 3305(b)(4)","specifics":"Inventory must record bias-testing status; it does not require testing or an impact assessment before use.","note":"Record-keeping only.","caveat":"Inventory field only; no testing duty, as the specifics concede."},{"part":"A","supported":"partial","quote":"(C)  address the use or prohibition of systems that have not been tested for bias or have been shown to contain bias; and","where":"3 V.S.A. 5012(c)(3)(C)","specifics":"The Division must report annually on needed policies on untested or biased systems; no binding duty.","note":"","caveat":"Division reports on needed policies; no binding duty."},{"part":"N","supported":"partial","quote":"(2)  whether the automated decision system gives notice to an individual impacted by the automated decision system of the fact that the automated decision system is in use and what information should be provided","where":"Sec. 7(b)(2)","specifics":"The AI Advisory Council must recommend (by Jan. 15, 2024) a policy on notifying individuals affected by an ADS; recommendation only, not a mandate.","note":"Found despite description saying notice not found; it is a recommendation duty.","caveat":"delayed or expires. Council only recommends a notice policy (due Jan. 15, 2024); no binding notice to individuals. Council section repealed June 30, 2027."},{"part":"H","supported":"partial","quote":"(C)  potential reversal by a human decision maker through a timely process clearly described and accessible to an individual impacted by the decision; and","where":"Sec. 7(b)(3)(C)","specifics":"Council must recommend protocols on appeal, suspension and human reversal of ADS decisions affecting legal rights, duties or privileges; recommendation only.","note":"Found despite description saying human review not found; not binding.","caveat":"Recommendation protocol only; no binding human review or appeal."},{"part":"V","supported":"partial","quote":"(A)  by requiring the vendor to create such an explanation;","where":"Sec. 7(b)(3)(A)","specifics":"Council recommendations must consider requiring vendors to create explanations; also vendor conflict-of-interest disclosure policies (Sec. 7(a)(2)); recommendation only.","note":"Not binding.","caveat":"Recommendation considers requiring vendor explanations; not binding."},{"part":"O","supported":"yes","quote":"There is established the Division of Artificial Intelligence within the Agency of Digital Services to review all aspects of artificial intelligence systems developed, employed, or procured in State government.","where":"3 V.S.A. 5012(a) (Sec. 5)","specifics":"Creates the Division of AI (with a Director) to review AI in state government, plus an Artificial Intelligence Advisory Council (5013) that advises the Director; no penalties or enforcement.","note":"Advisory/review body; no enforcement.","caveat":"Division sits inside Agency of Digital Services (not independent), reviews and reports only, no penalties; supports an advisory/review body at most."},{"part":"SCOPE","supported":"yes","quote":"\"Automated decision system\" means any algorithm, including one incorporating machine learning or other artificial intelligence techniques, that uses data-based analytics to make or support government decisions, judgments, or conclusions.","where":"3 V.S.A. 3305(a)(2)","specifics":"Covers any ADS making or supporting government decisions by state government; includes final and support systems.","note":"","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"whether any systems affect the constitutional or legal rights, duties, or privileges of any Vermont resident; and","where":"3 V.S.A. 5012(b)(3)(A)","specifics":"The Division must review the inventory for systems affecting legal rights, duties or privileges of residents; benefits or eligibility are not named.","note":"No benefits/Medicaid/SNAP wording.","caveat":""}]},"CA|AB 302":{"meta":{"version":"Chaptered","date":"2023-10-13","textUrl":"https://legiscan.com/CA/text/AB302/id/2845867","stateUrl":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240AB302#94CHP","legiscan":"https://legiscan.com/CA/bill/AB302/2023","status":4,"statusDate":"2023-10-13"},"q":[{"part":"I","supported":"yes","quote":"On or before September 1, 2024, the Department of Technology shall conduct, in coordination with other interagency bodies as it deems appropriate, a comprehensive inventory of all high-risk automated decision systems","where":"11546.45.5(b) (Sec. 1)","specifics":"Dept. of Technology must inventory all high-risk ADS proposed for use, developed, procured or used by state agencies by Sept. 1, 2024.","note":"","caveat":""},{"part":"I","supported":"yes","quote":"On or before January 1, 2025, and annually thereafter, the department shall submit a report of the comprehensive inventory described in subdivision (b) to the Assembly Committee on Privacy and Consumer Protection and the Senate Committee on Governmental Organization.","where":"11546.45.5(d)(1)","specifics":"Annual report of the inventory goes to two legislative committees, not clearly to the public.","note":"Public posting not required in text.","caveat":""},{"part":"A","supported":"partial","quote":"The measures in place, if any, to mitigate the risks, including cybersecurity risk and the risk of inaccurate, unfairly discriminatory, or biased decisions, of the automated decision system.","where":"11546.45.5(c)(4)(A)","specifics":"Inventory must describe existing risk mitigation measures (accuracy metrics, audits); does not require them.","note":"Reporting only; not a pre-use assessment duty.","caveat":"limited by conditions or exceptions. Inventory must describe mitigation measures 'if any'; no duty to assess or mitigate."},{"part":"O","supported":"partial","quote":"the department shall submit a report of the comprehensive inventory described in subdivision (b) to the Assembly Committee on Privacy and Consumer Protection and the Senate Committee on Governmental Organization.","where":"11546.45.5(d)(1)","specifics":"The Department of Technology is the responsible office and reports annually to the Legislature (inoperative Jan. 1, 2029); no enforcement or penalties.","note":"Weak oversight: reporting to legislature only.","caveat":"delayed or expires. Reporting to legislature only; Department is the inventory preparer, not an oversight authority. Report duty inoperative Jan. 1, 2029."},{"part":"SCOPE","supported":"yes","quote":"\"High-risk automated decision system\" means an automated decision system that is used to assist or replace human discretionary decisions that have a legal or similarly significant effect, including decisions that materially impact access to, or approval for, housing or accommodations, education, employment, credit, health care, and criminal justice.","where":"11546.45.5(a)(4)","specifics":"Covers high-risk ADS with legal or similarly significant effect: housing, education, employment, credit, health care, criminal justice. Public benefits, Medicaid, SNAP are not named.","note":"Health care is the closest; no benefits wording.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"Any state office, department, division, or bureau.","where":"11546.45.5(a)(5)(A)(i)","specifics":"State agencies include state offices, departments, CSU, Board of Parole Hearings and DCA boards; excludes UC, Legislature, judiciary and local governments.","note":"","caveat":"a definition, not itself a duty. Exclusion of UC, Legislature and judicial branch is explicit; local governments are not expressly excluded, just not listed."}]},"CA|SB 896":{"meta":{"version":"Chaptered","date":"2024-09-29","textUrl":"https://legiscan.com/CA/text/SB896/id/3023382","stateUrl":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240SB896#92CHP","legiscan":"https://legiscan.com/CA/bill/SB896/2023","status":4,"statusDate":"2024-09-29"},"q":[{"part":"N","supported":"yes","quote":"A state agency or department that utilizes GenAI to directly communicate with a person regarding government services and benefits shall ensure that those communications include both of the following: (a) A disclaimer that indicates to the person that the communication was generated by GenAI.","where":"11549.66 (Sec. 2)","specifics":"Agencies using generative AI to communicate directly with a person about government services and benefits must include a disclaimer (placement rules by medium) saying it was AI-generated.","note":"","caveat":"limited by conditions or exceptions. Disclosure is tied to GenAI communications with a person about services and benefits, not to a decision about them; codebook calls that loose. Quote splices the lead-in with (a)."},{"part":"A","supported":"partial","quote":"The Office of Emergency Services shall, as appropriate, perform a risk analysis of potential threats posed by the use of GenAI to California’s critical infrastructure, including those that could lead to mass casualty events.","where":"11549.65(b)(1)","specifics":"Cal OES performs (as appropriate) a risk analysis of GenAI threats to critical infrastructure and gives the Legislature an annual summary; not a pre-use assessment of agency GenAI.","note":"Narrow; not a testing or bias duty on agencies.","caveat":"limited by conditions or exceptions. 'As appropriate' qualifier; narrow risk analysis of GenAI threats to critical infrastructure by Cal OES, not assessment of agency systems."},{"part":"I","supported":"no","quote":"","where":"","specifics":"No inventory of generative AI uses by agencies appears in the enacted text; the Dept. of Technology only updates the Executive Order N-12-23 report (11549.65(a)).","note":"Tag I1 not supported."},{"part":"SCOPE","supported":"yes","quote":"A state agency or department that utilizes GenAI to directly communicate with a person regarding government services and benefits shall","where":"11549.66","specifics":"Covers state agency or department GenAI communications about government services and benefits; does not cover decisions or eligibility determinations, and not local governments.","note":"","caveat":""}]},"MT|HB 178":{"meta":{"version":"Enrolled","date":"","textUrl":"https://legiscan.com/MT/text/HB178/id/3212520","stateUrl":"https://docs.legmt.gov/download-ticket?ticketId=6acf2488-0490-4187-b84e-85aee3f10818","legiscan":"https://legiscan.com/MT/bill/HB178/2025","status":4,"statusDate":"2025-05-05"},"q":[{"part":"N","supported":"yes","quote":"if a government entity or state officer has an interface with the public that uses an artificial intelligence system, the use of the artificial intelligence system in the interface must be disclosed.","where":"Section 3(1)(b)","specifics":"Government must disclose AI use in public-facing interfaces.","note":"","caveat":"limited by conditions or exceptions. General disclosure of AI in public-facing interfaces, not tied to a decision about the person; at most loose N. Peace-officer exemption in 3(2)."},{"part":"N","supported":"yes","quote":"if a government entity or state officer publishes material produced by an artificial intelligence system that is not reviewed by a human in an appropriate responsible position, the material must be accompanied by a disclosure that the material was produced by an artificial intelligence system;","where":"Section 3(1)(a)","specifics":"AI-produced material published without human review must carry an AI disclosure; peace officers investigating crimes are exempt in limited cases (Sec. 3(2)).","note":"Does not require notice of an AI decision to the affected person.","caveat":"limited by conditions or exceptions. Applies only to published AI material not reviewed by a human; general disclosure, at most loose N. Description's 'AI-published material' omits the no-human-review condition."},{"part":"H","supported":"yes","quote":"the recommendation or decision must be reviewed and is subject to rejection or modification by a human in an appropriate responsible position.","where":"Section 4","specifics":"Any AI recommendation or decision for a government entity that could impact a person's rights, duties, or privileges and immunities must be reviewed, and can be rejected or changed, by a trained human.","note":"","caveat":""},{"part":"H","supported":"yes","quote":"\"Human in an appropriate responsible position\" means a human person who is a state officer or a public employee as those terms are defined in 2-2-102 who has reasonable training in the uses and limitations of artificial intelligence systems and is in a position to modify or reject the particular use of an artificial intelligence system.","where":"Section 1(4)","specifics":"Reviewer must be a trained state officer or public employee with power to modify or reject.","note":"","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"decision for a government entity or state officer that could impact the rights, duties, or privileges and immunities of a person, the recommendation or decision must be reviewed","where":"Section 4","specifics":"Review duty is triggered by AI recommendations or decisions that could affect a person's rights, duties, or privileges; benefits are not named.","note":"No benefits/Medicaid/SNAP wording.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"\"Government entity\" has the same meaning as provided in 46-5-110.","where":"Section 1(3)","specifics":"Applies to state and local government (per title: state and local government) through the 46-5-110 definition.","note":"Definition is by cross-reference; text of 46-5-110 not in file.","caveat":"a definition, not itself a duty"},{"part":"O","supported":"no","quote":"","where":"","specifics":"No oversight body, enforcement agency, penalty or private right of action in the bill.","note":"Not tagged; confirms none."}]},"AR|HB 1958 (Act 848)":{"meta":{"version":"Chaptered","date":"2025-04-21","textUrl":"https://legiscan.com/AR/text/HB1958/id/3217014","stateUrl":"https://arkleg.state.ar.us/Acts/FTPDocument?path=%2FACTS%2F2025R%2FPublic%2F&file=848.pdf&ddBienniumSession=2025%2F2025R","legiscan":"https://legiscan.com/AR/bill/HB1958/2025","status":4,"statusDate":"2025-04-17"},"q":[{"part":"H","supported":"yes","quote":"Requires an authorized human employee or designee to","where":"25-1-128(b)(3)(B) (Sec. 1)","specifics":"Each public entity's AI policy must require an authorized human employee to make any final decision regardless of AI recommendation.","note":"","caveat":""},{"part":"O","supported":"partial","quote":"A public entity shall create a disciplinary procedure for a","where":"25-1-128(e)","specifics":"Each public entity must create its own disciplinary procedure for violating the AI policy; internal enforcement only, no central oversight body.","note":"Extra; weak.","caveat":"Employee disciplinary procedure created by each entity itself; not an oversight body or external enforcement. Sentence mixes old and new words in the file."},{"part":"N","supported":"no","quote":"","where":"","specifics":"No notice or disclosure to affected individuals; policies must only be available to the public on request for state entities (25-1-128(c)(1)).","note":""},{"part":"SCOPE","supported":"yes","quote":"\"Automated decision tool\" means a system or service that","where":"25-1-128(a)(2)","specifics":"Covers automated decision tools used for consequential decisions by public entities.","note":"Text shows struck/added mixing nearby; this passage is the new definition.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"Public entity\" means an instrumentality funded in whole","where":"25-1-128(a)(4)","specifics":"Covers state departments (incl. Human Services, Health), political subdivisions, school districts and higher education.","note":"Benefits not named, though Dept. of Human Services is listed.","caveat":"a definition, not itself a duty"},{"part":"A","supported":"no","quote":"","where":"","specifics":"No impact assessment or testing duty; only a policy on authorized use plus training (25-1-128(b)(4)).","note":""}]},"IN|SB 150":{"meta":{"version":"Enrolled","date":"2024-03-07","textUrl":"https://legiscan.com/IN/text/SB0150/id/2953970","stateUrl":"https://iga.in.gov/pdf-documents/123/2024/senate/bills/SB0150/SB0150.06.ENRH.pdf","legiscan":"https://legiscan.com/IN/bill/SB0150/2024","status":4,"statusDate":"2024-03-13"},"q":[{"part":"I","supported":"partial","quote":"Not later than November 1, 2025, each state agency may: (1) compile, in a form specified by the office, an inventory of all artificial intelligence technologies that are: (A) in use; or","where":"IC 4-13.1-5-3(a) (Sec. 3)","specifics":"Each state agency may (permissive wording in the file) compile an inventory of AI in use or under consideration and submit it to the technology office and the AI task force; contents include vendor, purpose, whether it informs or makes decisions, bias evaluation, costs.","note":"Wording is 'may', and the file mixes enacted/struck text; no public posting required, only submission to the office and the task force. Description's 'shall' unverified.","caveat":"permissive (\"may\"), not mandatory; delayed or expires. Permissive 'may' (not 'shall'); duty is optional. Specifics acknowledge this."},{"part":"I","supported":"partial","quote":"(4) Whether the artificial intelligence technology provides: (A) the state agency with information or data that is used by the state agency to inform decisions made by the state agency; or (B) decisions, without human intervention, that are implemented by the state agency.","where":"IC 4-13.1-5-3(b)(4)","specifics":"Each inventory entry says whether the AI informs decisions or makes them without human intervention.","note":"","caveat":"permissive (\"may\"), not mandatory; delayed or expires"},{"part":"A","supported":"partial","quote":"(11) Whether the data or information produced by the artificial intelligence technology has been: (A) evaluated for bias; and (B) found to exhibit bias.","where":"IC 4-13.1-5-3(b)(11)","specifics":"Inventory records whether AI output was evaluated for bias and found biased; no testing duty. Also records independent third-party testing (b)(10).","note":"Extra tag; record-keeping only.","caveat":"permissive (\"may\"), not mandatory; delayed or expires. Inventory field only, on an optional inventory; no testing duty."},{"part":"V","supported":"partial","quote":"(1) The vendor of the artificial intelligence technology.","where":"IC 4-13.1-5-3(b)(1)","specifics":"Inventory must identify the vendor; no vendor duties.","note":"Weak.","caveat":"permissive (\"may\"), not mandatory. Vendor named in optional inventory; no vendor duty."},{"part":"O","supported":"yes","quote":"The artificial intelligence task force is established as a temporary task force serving the general assembly.","where":"IC 2-5-53.7-4 (Sec. 1)","specifics":"Creates a 15-member temporary AI task force to study agency AI use and report annually by Oct. 31 recommending policy; no enforcement; expires Dec. 31, 2027.","note":"Study body only; no enforcement.","caveat":"delayed or expires. Temporary legislative study body; advisory only. Label IC 2-5-53.7-4 is correct (Sec. 4 of the new chapter in SECTION 1). Expires Dec. 31, 2027."},{"part":"SCOPE","supported":"yes","quote":"effects of state agency use of artificial intelligence technology on the rights and interests of Indiana residents, including on the: (i) constitutional and legal rights; (ii) privacy interests; (iii) employment; and (iv) economic welfare;","where":"IC 2-5-53.7-8(2)(B)","specifics":"Task force assesses effects of state agency AI on residents' rights and interests; covers executive and legislative agencies (not judicial) and all AI in use or considered.","note":"No benefits/eligibility wording.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"(1) means an authority, a board, a branch, a commission, a committee, a department, a division, or another instrumentality of: (A) the executive, including the administrative; or (B) the legislative; department of state government; and (2) does not include the judicial department of state government.","where":"IC 4-13.1-5-2","specifics":"State agency definition for the inventory; excludes the judiciary and local governments.","note":"","caveat":"a definition, not itself a duty. Excludes the judicial department explicitly; local governments are not expressly excluded, simply not listed."}]},"KY|SB 4":{"meta":{"version":"Chaptered","date":"","textUrl":"https://legiscan.com/KY/text/SB4/id/3226737","stateUrl":"https://apps.legislature.ky.gov/law/acts/25RS/documents/0066.pdf","legiscan":"https://legiscan.com/KY/bill/SB4/2025","status":4,"statusDate":"2025-03-24"},"q":[{"part":"I","supported":"yes","quote":"(d) Maintaining a centralized registry to include current inventory of generative artificial intelligence systems and high-risk artificial intelligence systems; and","where":"Sec. 3(1)(d)","specifics":"The AI Governance Committee must maintain a central registry/inventory of generative and high-risk AI systems used by agencies.","note":"Public availability not stated.","caveat":""},{"part":"I","supported":"yes","quote":"1. The artificial intelligence registry, which shall include the current inventory and use case of artificial intelligence utilized in state government;","where":"Sec. 3(11)(a)1","specifics":"COT reports the registry to the Legislative Research Commission and interim committee by Dec. 1, 2025 and annually; reported to legislators, not explicitly published.","note":"","caveat":""},{"part":"N","supported":"yes","quote":"1. Disclose how artificial intelligence is used in the decision-making process; 2. Provide the extent of human involvement in validating and oversight of any decision made; and 3. Make readily available options for individuals to appeal a consequential decision that involves artificial intelligence.","where":"Sec. 3(6)(b)","specifics":"When AI makes external decisions about citizens, the agency must disclose how AI is used, the extent of human involvement, and make appeal options available.","note":"","caveat":"limited by conditions or exceptions"},{"part":"N","supported":"yes","quote":"A department, agency, or administrative body shall disclose to the public, through a clear and conspicuous disclaimer, when generative artificial intelligence, artificial intelligence systems, or other artificial intelligence-related capabilities are used: 1. To render any decision regarding individual citizens or businesses within the state;","where":"Sec. 3(6)(a)","specifics":"Agencies must post a clear and conspicuous disclaimer when AI is used to render decisions about individuals or businesses, to inform decisions, or to produce public outputs.","note":"","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"yes","quote":"Operating standards for utilization of high -risk artificial intelligence systems shall prohibit the use of a high-risk artificial intelligence system to render a consequential decision without the design and implementation of a risk management policy and program for high -risk artificial intelligence systems.","where":"Sec. 3(8)(a)","specifics":"High-risk AI may not render consequential decisions without a risk management policy and program that identifies, mitigates and documents bias; must follow ISO/IEC 42001 or another recognized framework.","note":"","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"partial","quote":"(a) How the artificial intelligence system will not result in unlawful discrimination against any individual or group of individuals;","where":"Sec. 3(5)(a)","specifics":"COT executive director must consider and document how each AI system avoids unlawful discrimination, plus risks and mitigation (5)(d).","note":"","caveat":"Consider-and-document duty on COT executive director, not explicitly per system or pre-use testing; specifics' 'each AI system' is an inference."},{"part":"H","supported":"yes","quote":"2. Requiring review and intervention by hum ans dependent on the use case and potential risk for all outcomes from generative and high-risk artificial intelligence systems; and","where":"Sec. 3(2)(b)2","specifics":"Committee policies must require human review and intervention scaled to use case and risk for outcomes of generative and high-risk AI; appeal option in Sec. 3(6)(b)3.","note":"","caveat":""},{"part":"V","supported":"yes","quote":"1. Ensuring artificial intelligence models have comprehensive and complete documentation that is available for review and inspection;","where":"Sec. 3(2)(b)1","specifics":"Agencies must ensure AI models have complete documentation open to review; disclaimers must include developer system cards (Sec. 3(6)(c)); COT also reviews third-party developers and contractors (Sec. 3(11)(a)3).","note":"Obligations fall on agencies to obtain vendor documentation, not on vendors directly.","caveat":"limited by conditions or exceptions. Committee must develop policies so agencies ensure model documentation; duty lies on agencies, not vendors. 'Developer' is defined as an agency. Trade-secret carve-out in Sec. 3(9)."},{"part":"O","supported":"yes","quote":"The Commonwealth Office of Technology shall create an Artificial Intelligence Governance Committee to govern the use of artificial intelligence systems by state departments, state agencies, and state administrative bodies by:","where":"Sec. 3(1)","specifics":"COT creates an AI Governance Committee to set standards, keep the registry and approval process, with annual reports to the LRC; COT must issue regulations by Dec. 1, 2025.","note":"No penalties or AG enforcement.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"(a) Means any artificial intelligence system that is a substantial factor in the decision -making process or specifically intended to autonomously make, or be a substantial factor in making, a consequential decision; and","where":"Sec. 1(12)(a)","specifics":"High-risk AI is defined by substantial role in consequential decisions; applies to state departments, agencies and administrative bodies; benefits not named in the text found.","note":"'Consequential decision' definition is not clearly in the file; no Medicaid/SNAP wording found.","caveat":"a definition, not itself a duty; limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"to govern the use of artificial intelligence systems by state departments, state agencies, and state administrative bodies","where":"Sec. 3(1)","specifics":"Covers state departments, agencies and administrative bodies (executive branch).","note":"","caveat":""}]},"TX|HB 2060":{"meta":{"version":"Enrolled","date":"2023-05-26","textUrl":"https://legiscan.com/TX/text/HB2060/id/2819574","stateUrl":"https://capitol.texas.gov/tlodocs/88R/billtext/html/HB02060F.htm","legiscan":"https://legiscan.com/TX/bill/HB2060/2023","status":4,"statusDate":"2023-06-13"},"q":[{"part":"I","supported":"yes","quote":"Not later than July 1, 2024, each agency in the executive and legislative branches of state government, using money appropriated to the agency by this state, shall submit an inventory report of all automated decision systems that are being developed, employed, or procured by the agency.","where":"Sec. 2054.623(a)","specifics":"Each executive and legislative branch agency must submit an inventory report of all ADS by July 1, 2024 (name, vendor, capabilities, bias testing, purpose, fiscal impacts) to the department, the council and legislative committees.","note":"Extra tag (not in current tags). Submitted to bodies, not required to be public.","caveat":"delayed or expires. Whole subchapter expires Jan 1, 2025 (2054.624) and the deadline was July 1, 2024; specifics and description do not mention expiry. Reports go to DIR, council and committees, not public."},{"part":"O","supported":"yes","quote":"The council shall study and monitor artificial intelligence systems developed, employed, or procured by state agencies.","where":"Sec. 2054.622(f)","specifics":"Seven-member AI Advisory Council studies and monitors agency AI, reviews inventories for effects on legal rights, duties, or privileges, and reports to the legislature by Dec. 1, 2024; abolished Jan. 1, 2025.","note":"Advisory, temporary; no enforcement.","caveat":"delayed or expires"},{"part":"V","supported":"partial","quote":"(1) the name and vendor of the automated decision system, if any;","where":"Sec. 2054.623(a)(1)","specifics":"Inventory names the vendor; no vendor duties.","note":"Weak.","caveat":"delayed or expires; a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"(A) the effect of the automated decision systems on the constitutional or legal rights, duties, or privileges of the residents of this state; and","where":"Sec. 2054.622(f)(2)(A)","specifics":"Council reviews ADS inventories for effect on residents' legal rights, duties or privileges; applies to executive and legislative branch state agencies; benefits not named.","note":"No benefits/eligibility wording.","caveat":"delayed or expires"},{"part":"SCOPE","supported":"yes","quote":"\"Automated decision system\" means an algorithm, including an algorithm incorporating machine learning or other artificial intelligence techniques, that uses data-based analytics to make or support governmental decisions, judgments, or conclusions.","where":"Sec. 2054.621(3)","specifics":"Covers ADS that make or support governmental decisions.","note":"","caveat":"a definition, not itself a duty; delayed or expires"}]},"UT|HB 444 / HB 450":{"meta":{"version":"Enrolled","date":"2025-03-12","textUrl":"https://legiscan.com/UT/text/HB0444/id/3168415","stateUrl":"https://le.utah.gov/Session/2025/bills/enrolled/HB0444.pdf","legiscan":"https://legiscan.com/UT/bill/HB0444/2025","status":4,"statusDate":"2025-03-27"},"q":[{"part":"A","supported":"partial","quote":"(b)  \"High-risk processing activities\" may include the use of:","where":"Section 6, 63A-19-101(17)(b)","specifics":"Defines automated decision making and profiling as examples of governmental entities' high-risk processing; the Office of Data Privacy must monitor high-risk processing.","note":"Definition only; no mandated pre-use assessment.","caveat":"a definition, not itself a duty; permissive (\"may\"), not mandatory. Wrong section label: definitions are in Section 6 of HB 444 (63A-19-101), not Sec. 3. Quote is a permissive definition ('may include') and does not itself show the monitoring duty claimed in specifics (that is 63A-19-301(3)(d))."},{"part":"A","supported":"partial","quote":"(b)  create assessment tools and resources that a governmental entity may use to:","where":"63A-19-301(4)(b) (UT_HB444)","specifics":"The Office of Data Privacy may create tools for entities to assess privacy impact and risk; optional.","note":"Optional ('may'), not binding.","caveat":"permissive (\"may\"), not mandatory. Optional ('may') tools; also (4) renumbered from former (6). Specifics concede it is optional."},{"part":"O","supported":"yes","quote":"(c)  for a violation that the state auditor substantiates, provide an opportunity for the","where":"63A-19-601(1)(c) (UT_HB444)","specifics":"State auditor investigates violations on board instruction and gives a 30-day cure; uncured violations go to the AG (non-state entities) for injunction or to the Legislative Management Committee (state agencies).","note":"General government privacy enforcement, not ADM-specific.","caveat":"the quote cuts off part of the sentence; limited by conditions or exceptions. Quote cut mid-sentence; general government privacy enforcement, not ADM-specific; no penalties, referral to Legislative Management Committee for state agencies."},{"part":"O","supported":"yes","quote":"(3)  After referral by the state auditor under Subsection (2)(a), the attorney general may file","where":"63A-19-601(3) (UT_HB444)","specifics":"AG may sue to enjoin or compel compliance by local governmental entities after referral.","note":"","caveat":"the quote cuts off part of the sentence; limited by conditions or exceptions. Quote cut mid-sentence; AG action covers governmental entities that are not state agencies (not only local governments)."},{"part":"V","supported":"partial","quote":"(2)  A contract entered into or renewed between a contractor and a governmental entity after","where":"63A-19-401.4(2) (UT_HB444)","specifics":"Government contracts after July 1, 2026 must require contractors processing personal data to comply with the privacy chapter; not ADM-specific.","note":"General privacy contractor duty.","caveat":"the quote cuts off part of the sentence. General privacy contractor clause for personal data, not AI or vendor documentation; quote is truncated."},{"part":"N","supported":"no","quote":"","where":"","specifics":"No notice or explanation duty specific to ADM; privacy notices are general.","note":""},{"part":"SCOPE","supported":"yes","quote":"\"High-risk processing activities\" means a governmental entity's processing","where":"63A-19-101(17)(a) (UT_HB444)","specifics":"Scope is governmental entities' processing of personal data; ADM and profiling are named examples; benefits/eligibility not named.","note":"","caveat":"a definition, not itself a duty. In HB 444 the text mixes struck and new words ('[High risk] High-risk'); clean wording is in HB 450 where it is (18)(a). ADM is only a 'may include' example."},{"part":"SCOPE","supported":"yes","quote":"\"Governmental entity\" means the same as that term is defined in Section 63G-2-103.","where":"63A-19-101(15) (UT_HB444) / 63A-12-100.5","specifics":"Applies to all governmental entities under GRAMA, including state agencies and political subdivisions.","note":"","caveat":"a definition, not itself a duty"},{"part":"O","supported":"partial","quote":"(d)  monitor high-risk data processing activities within governmental entities;","where":"63A-19-301(3)(d) (UT_HB450)","specifics":"UT_HB450 (2026): Utah Office of Data Privacy must monitor high-risk data processing activities within governmental entities.","note":"From UT_HB450, clean text.","caveat":"Monitoring is general high-risk privacy processing (of which ADM is only an optional example); not enforcement."},{"part":"O","supported":"yes","quote":"There is created within the office the position of data privacy","where":"63A-19-501(1) (UT_HB450)","specifics":"UT_HB450 creates a data privacy ombudsperson in the Office of Data Privacy to mediate complaints about governmental entities.","note":"","caveat":"Ombudsperson mediates only; may not audit or enforce. HB 444 already created a governor-appointed ombudsperson (63A-19-501); HB 450 moves it into the office."},{"part":"SCOPE","supported":"yes","quote":"(b)  \"High-risk processing activities\" may include the use of:","where":"63A-19-101(18)(b) (UT_HB450)","specifics":"UT_HB450 repeats ADM and profiling as examples of high-risk governmental processing.","note":"","caveat":"a definition, not itself a duty; permissive (\"may\"), not mandatory"}]},"NC|H 565":{"meta":{"version":"Amended","date":"2026-06-23","textUrl":"https://legiscan.com/NC/text/H565/id/3450162","stateUrl":"https://www.ncleg.gov/Sessions/2025/Bills/House/PDF/H565v5.pdf","legiscan":"https://legiscan.com/NC/bill/H565/2025","status":2,"statusDate":"2025-05-01"},"q":[{"part":"H","supported":"partial","quote":"p) Artificial Intelligence. – An artificial intelligence-based algorithm shall not be used 21 as the sole basis to deny a utilization review determination.\"","where":"Section 1.(a), G.S. 58-50-61(p)","specifics":"Insurers may not use an AI algorithm as the sole basis to deny a utilization review determination.","note":"Sole-basis ban only; no explicit human-review, appeal or reconsideration duty.","caveat":"delayed or expires"},{"part":"H","supported":"partial","quote":"amend DHB's contracts with prepaid health plans 24 to include a prohibition on the use of an artificial intelligence -based algorithm as the sole b asis 25 to deny a utilization review or prior authorization determination.","where":"Section 1.(b)","specifics":"The Medicaid agency (DHB) must, as soon as practicable, amend its prepaid health plan contracts to bar AI as the sole basis to deny utilization review or prior authorization.","note":"Medicaid-specific; contract-based.","caveat":""},{"part":"V","supported":"partial","quote":"Developers shall not design, trai n, or materially modify an AI system for use in 24 healthcare coding, billing, or documentation if the system is designed to promote, incentivize, or 25 systematically result in upcoding.","where":"Section 2.(a), G.S. 90-413(a)","specifics":"AI developers may not build or modify AI for healthcare coding/billing that is designed to promote upcoding.","note":"Developer duty exists but is about provider billing upcoding, not documentation to an agency or Medicaid decision-making; the Medicaid utilization-review part has no vendor duty.","caveat":"the quote cuts off part of the sentence"},{"part":"O","supported":"yes","quote":"only the Attorney General may bring an action 32 pursuant to this subsection. No action may be brought by a private individual.","where":"Section 2.(a), G.S. 90-413(b)","specifics":"Repeated violations of the billing-AI limits are unfair trade practices that only the Attorney General may sue on; no private right of action.","note":"Enforcement applies to the billing/upcoding part, not the utilization-review denial ban.","caveat":""},{"part":"O","supported":"partial","quote":"The Department may deny enrollment or terminate the enrollment of a 49 healthcare provider who is not in compliance with this section or with G.S.","where":"Section 2.(b), G.S. 108C-15(b)","specifics":"The Medicaid department may deny or terminate Medicaid enrollment of a provider that does not file the AI compliance attestation or follows the billing limits.","note":"Provider attestation due starting July 1, 2027, copy to Attorney General (108C-15(a)).","caveat":"the quote cuts off part of the sentence; permissive (\"may\"), not mandatory; delayed or expires. Specifics say provider 'does not file the attestation or follows the billing limits'; text says not in compliance with section 108C-15 or G.S. 90-413 (should read 'violates'). Quote is cut mid-citation. 'May' is discretionary; attestation starts July 1, 2027."},{"part":"SCOPE","supported":"yes","quote":"Developers shall not design, trai n, or materially modify an AI system for use in 24 healthcare coding, billing, or documentation if the system is designed to promote, incentivize, or 25 systematically result in upcoding.","where":"Section 2.(a), G.S. 90-413(a)","specifics":"Part II reaches health care providers (including those billing Medicaid) and AI developers, not state agency decisions.","note":"","caveat":"the quote cuts off part of the sentence"}]},"MI|HB 4537":{"meta":{"version":"Introduced","date":"2025-06-03","textUrl":"https://legiscan.com/MI/text/HB4537/id/3250675","stateUrl":"https://legislature.mi.gov/documents/2025-2026/billintroduced/House/htm/2025-HIB-4537.htm","legiscan":"https://legiscan.com/MI/bill/HB4537/2025","status":1,"statusDate":"2025-06-03"},"q":[{"part":"H","supported":"partial","quote":"The department or a contracted health plan shall not deny, modify, or delay a claim under the medical assistance program based on a review using artificial intelligence.","where":"Sec. 107b","specifics":"The Medicaid department or a contracted health plan may not deny, modify or delay a medical assistance claim based on an AI review.","note":"Outright ban on AI-based review outcomes; no express human-review or appeal mechanism. Text is a one-section bill.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"A bill to amend 1939 PA 280, entitled \"The social welfare act,\" (MCL 400.1 to 400.119b) by adding section 107b.","where":"Title","specifics":"Amends the Social Welfare Act to cover claims under the medical assistance (Medicaid) program, for both the department and contracted health plans.","note":"","caveat":"findings or preamble, not operative law. Title does not mention Medicaid or contracted plans; those come from the operative sentence. Quote only shows the amended act."}]},"NY|A 7278":{"meta":{"version":"Introduced","date":"2025-03-21","textUrl":"https://legiscan.com/NY/text/A07278/id/3184684","stateUrl":"https://assembly.state.ny.us/leg/?default_fld=&bn=A07278&term=2025&Summary=Y&Actions=Y&Text=Y&Committee%26nbspVotes=Y&Floor%26nbspVotes=Y#A07278","legiscan":"https://legiscan.com/NY/bill/A07278/2025","status":1,"statusDate":"2025-03-21"},"q":[{"part":"H","supported":"yes","quote":"All 19 decisions affecting individuals' rights, benefits, or services must be 20 made by human personnel","where":"Section 1, new State Technology Law 106-c, subd. 2","specifics":"State agencies and state-owned entities may not use LLMs or AI to make decisions affecting rights, benefits or services; human personnel must make all such decisions.","note":"Advisory AI use is allowed if humans make the final decision (subd. 3(a)).","caveat":"limited by conditions or exceptions"},{"part":"O","supported":"yes","quote":"The attorney general shall have the authority to investigate 6 violations of this section and take appropriate legal action to enforce 7 its provisions.","where":"Section 1, 106-c, subd. 5","specifics":"The attorney general may investigate violations and take legal action to enforce the ban.","note":"No penalties or private right of action are specified.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"No state agency or state-owned entity shall implement or utilize 17 large language models or any artificial intelligence systems to make 18 decisions that affect individuals' rights, benefits, or services.","where":"Section 1, 106-c, subd. 2","specifics":"Covers all state agencies and state-owned entities (including public universities and state-run hospitals) for decisions on rights, benefits or services.","note":"","caveat":"limited by conditions or exceptions"}]},"CA|SB 1248":{"meta":{"version":"Introduced","date":"2026-02-19","textUrl":"https://legiscan.com/CA/text/SB1248/id/3369344","stateUrl":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202520260SB1248#99INT","legiscan":"https://legiscan.com/CA/bill/SB1248/2025","status":1,"statusDate":"2026-02-19"},"q":[{"part":"H","supported":"yes","quote":"The state agency shall require that any output of an automated decision system that suggests noneligibility or other adverse action be reviewed by a human before any adverse action is taken.","where":"Section 2, Gov. Code 12898.1(d)","specifics":"State agencies must have a human review any ADS output suggesting noneligibility or other adverse action before acting on it.","note":"Also 12898.1(c): no adverse determination on ADS output as the sole basis, unless federal or state law expressly authorizes it.","caveat":"limited by conditions or exceptions"},{"part":"H","supported":"yes","quote":"The state agency shall not use an output from an automated decision system as the sole basis for an adverse service determination affecting a natural person, such as denial of a benefit or license, except as expressly authorized by federal or state law.","where":"Section 2, Gov. Code 12898.1(c)","specifics":"State agencies may not use ADS output as the sole basis for denying a benefit or license.","note":"","caveat":"limited by conditions or exceptions"},{"part":"N","supported":"partial","quote":"When the use of an automated decision system is material to a decision, the state agency shall provide a means, consistent with applicable law, to document or disclose that the system was used in the decisionmaking process.","where":"Section 2, Gov. Code 12898.1(f)","specifics":"When an ADS is material to a decision, the agency must provide a means to document or disclose its use.","note":"Disclosure is not clearly directed to the affected person and there is no adverse-decision explanation requirement.","caveat":""},{"part":"A","supported":"partial","quote":"Monitor and periodically evaluate the use of automated decision systems to reduce the risk that outputs contain or perpetuate bias, including bias based on race, color, religion, sex, gender, gender identity, gender expression, sexual orientation, marital status, national origin, ancestry, age, disability, medical condition, genetic information, immigration or citizenship status, or any other characteristic protected by federal or state law.","where":"Section 2, Gov. Code 12898.1(g)(2)","specifics":"State agencies must monitor and periodically evaluate ADS use to reduce bias; the director must provide initial and periodic quality control review of outputs (12898.1(i)).","note":"No pre-use impact assessment or required report; no discontinuation duty.","caveat":""},{"part":"O","supported":"partial","quote":"The Government Operations Agency, in collaboration with any other state entity the agency deems appropriate, may develop, adopt, and make publicly available guidance for a state agency’s use of automated decision systems consistent with this chapter. Before issuing the guidance, the agency shall notify the Joint Legislative Budget Committee","where":"Section 2, Gov. Code 12898.2","specifics":"GovOps may (not must) issue public guidance on state agency ADS use, after notifying the Joint Legislative Budget Committee, and may give technical assistance (12898.3).","note":"Permissive guidance and assistance only; no enforcement mechanism or penalties.","caveat":"permissive (\"may\"), not mandatory; the quote cuts off part of the sentence"},{"part":"SCOPE","supported":"yes","quote":"Services” means both of the following: (1) Services, benefits, or assistance, whether provided in cash or in kind, that a state agency provides or administers, including, but not limited to, social services, linkages to programs administered by the federal Social Security Administration, vocational and education-related services, and employment assistance.","where":"Section 2, Gov. Code 12898(g)","specifics":"Covers state agency ADS used for public benefits and services (cash or in kind) and for professional license decisions.","note":"Digest describes this as public benefits and professional licenses; Medicaid and SNAP are not named in the operative text.","caveat":"a definition, not itself a duty. Quote covers (g)(1) benefits; the professional-license part in the specifics is (g)(2), not quoted."},{"part":"SCOPE","supported":"yes","quote":"If a state agency uses an automated decision system for services, not including competitive determinations, the state agency shall comply with all of the following:","where":"Section 2, Gov. Code 12898.1","specifics":"The obligations apply whenever a state agency uses an ADS for services, excluding competitive determinations.","note":"This is a limit-and-authorize bill: findings (SEC. 1(e)) say it authorizes agencies to use ADS for licensing and benefits determinations subject to safeguards.","caveat":"limited by conditions or exceptions"}]},"CA|SB 430":{"meta":{"version":"Amended","date":"2026-01-05","textUrl":"https://legiscan.com/CA/text/SB430/id/3300006","stateUrl":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202520260SB430#98AMD","legiscan":"https://legiscan.com/CA/bill/SB430/2025","status":6,"statusDate":"2026-02-02"},"q":[{"part":"H","supported":"yes","quote":"The local agency shall require that any output of an automated decision system that suggests noneligibility or other adverse action be reviewed by a human before any adverse action is taken.","where":"Section 2, Gov. Code 51021(d)","specifics":"Local agencies must have a human review any ADS output suggesting noneligibility or other adverse action before acting on it.","note":"","caveat":"limited by conditions or exceptions"},{"part":"H","supported":"yes","quote":"The local agency shall not use an output from an automated decision system as the sole basis for an adverse eligibility or benefit determination affecting a natural person, except as expressly authorized by federal or state law.","where":"Section 2, Gov. Code 51021(c)","specifics":"Local agencies may not use ADS output as the sole basis for an adverse eligibility or benefit determination unless law expressly authorizes it.","note":"","caveat":"limited by conditions or exceptions"},{"part":"N","supported":"partial","quote":"When the use of an automated decision system is material to a decision, the local agency shall provide a means, consistent with applicable law, to document or disclose that the system was used in the decisionmaking process. The public shall be offered an opportunity to opt-out of an automated decision system for supportive services determinations, if possible.","where":"Section 2, Gov. Code 51021(f)","specifics":"Where an ADS is material to a decision, the local agency must provide a means to document or disclose its use, and should offer an opt-out for supportive services determinations if possible.","note":"Disclosure duty is general; no individual adverse-decision explanation.","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"partial","quote":"Monitor and periodically evaluate the use of automated decision systems to reduce the risk that outputs contain or perpetuate bias, including bias based on race, color, religion, sex, gender, gender identity, gender expression, sexual orientation, marital status, national origin, ancestry, age, disability, medical condition, genetic information, immigration or citizenship status, or any other characteristic protected by federal or state law.","where":"Section 2, Gov. Code 51021(g)(2)","specifics":"Local agencies must monitor and periodically evaluate ADS for bias; the governing board must provide initial and periodic audits or quality control review of outputs (51021(i)).","note":"No pre-use impact assessment; no discontinuation duty.","caveat":""},{"part":"O","supported":"partial","quote":"The Government Operations Agency, in collaboration with any other state agencies the agency deems appropriate, may develop, adopt, and make publicly available guidance for a local agency’s use of automated decision systems consistent with this chapter. Before issuing the guidance, the agency shall notify the Joint Legislative Budget Committee","where":"Section 2, Gov. Code 51022","specifics":"GovOps may issue public guidance after notifying the Joint Legislative Budget Committee and may provide technical assistance (51023).","note":"Permissive only; no enforcement.","caveat":"permissive (\"may\"), not mandatory; the quote cuts off part of the sentence"},{"part":"SCOPE","supported":"yes","quote":"Delays in processing CalFresh applications, approving MediCal benefits, and granting local building permits impose significant hardships on California residents.","where":"Section 1(b) (findings)","specifics":"Findings name CalFresh (SNAP) and Medi-Cal as the kinds of local-agency processing the bill is meant to speed with safeguards.","note":"Operative text does not name these programs; it covers 'supportive services'. Bill is aimed at local agencies (cities, counties, special districts), not state agencies.","caveat":"findings or preamble, not operative law"},{"part":"SCOPE","supported":"yes","quote":"If a local agency uses an automated decision system to confer supportive services, including eligibility services, benefits, and assistance, permits, or licenses for which the recipient applies or would have otherwise had to apply, not including competitive determinations, the local agency shall comply with all of the following:","where":"Section 2, Gov. Code 51021","specifics":"Applies to local agencies using ADS to confer supportive services, eligibility, benefits, permits or licenses.","note":"","caveat":"limited by conditions or exceptions"}]},"CA|AB 2412":{"meta":{"version":"Amended","date":"2026-06-16","textUrl":"https://legiscan.com/CA/text/AB2412/id/3448809","stateUrl":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202520260AB2412#97AMD","legiscan":"https://legiscan.com/CA/bill/AB2412/2025","status":2,"statusDate":"2026-05-04"},"q":[{"part":"N","supported":"yes","quote":"uses GenAI to directly communicate with the public, including through both individualized direct communications and general public announcements,","where":"Section 1, Gov. Code 11549.66(a)","specifics":"State agencies that use generative AI to communicate with the public must include a disclaimer that the communication was generated by GenAI.","note":"Disclosure that AI is being used in communications; not an explanation of adverse decisions. Text is a redline with struck and new wording mixed, so check the digest.","caveat":""},{"part":"N","supported":"yes","quote":"For written communications involving continuous online interaction","where":"Section 1, 11549.66(a)(1)(B)","specifics":"Chatbot interactions must show the GenAI disclaimer throughout; audio disclaimers are given orally at the start and end.","note":"","caveat":"the quote cuts off part of the sentence. Quote is a fragment ('interaction' vs text 'interactions'); audio start-and-end oral disclaimer in the specifics is (a)(1)(C), not in the quote."},{"part":"SCOPE","supported":"yes","quote":"Existing law requires a state agency or department that utilizes generative artificial intelligence (GenAI) to directly communicate with a person regarding government services and benefits to ensure that those communications include a disclaimer that indicates to the person that the communication was generated by GenAI, as specified, and information describing how a person may contact a human employee of the state agency or department.","where":"Legislative Counsel's Digest","specifics":"Existing law applies to GenAI communications about government services and benefits; the bill widens it to all public communications including general announcements.","note":"Covers communications only, not eligibility or other decisions.","caveat":"findings or preamble, not operative law"}]},"IL|HB 3567":{"meta":{"version":"Introduced","date":"2025-02-07","textUrl":"https://legiscan.com/IL/text/HB3567/id/3108191","stateUrl":"https://www.ilga.gov/Legislation/BillStatus/FullText?LegDocId=202045&DocName=10400HB3567&DocNum=3567&DocTypeID=HB&LegID=162257&GAID=18&SessionID=114&SpecSess=&Session=","legiscan":"https://legiscan.com/IL/bill/HB3567/2025","status":1,"statusDate":"2025-02-07"},"q":[{"part":"H","supported":"yes","quote":"shall not utilize or apply any automated 2 decision-making system, directly or indirectly, without 3 continuous meaningful human review when performing any 4 function that: 5 (1) is related to the delivery of any public 6 assistance benefit;","where":"Section 10(a)","specifics":"State agencies and their contractors may not use an ADS without continuous meaningful human review when the function relates to public assistance benefits, materially affects rights or safety, or affects statutory or constitutional rights.","note":"","caveat":""},{"part":"H","supported":"yes","quote":"review, oversight, and 2 control of the automated decision-making process by one or 3 more individuals who understand the risks, limitations, and 4 functionality of, and are trained to use, the automated 5 decision-making system and who have the authority to intervene 6 or alter the decision under review, including, but not limited 7 to, the ability to approve, deny, or modify any decision","where":"Section 5 (definitions)","specifics":"Reviewers must understand and be trained on the system and have authority to approve, deny or modify any decision.","note":"","caveat":"a definition, not itself a duty"},{"part":"A","supported":"yes","quote":"shall conduct 7 an impact assessment bearing the signature of one or more 8 individuals responsible for meaningful human review for the 9 lawful application and use of the automated decision-making 10 system. Following the first impact assessment, an impact 11 assessment shall be conducted in accordance with this Section 12 at least once every 2 years.","where":"Section 15(a)","specifics":"Agencies must conduct an impact assessment before use, at least every 2 years after the first, and before any material change, with testing for accuracy, fairness, bias and discrimination.","note":"Impact assessment must include testing for bias (15(a)(4)(A)).","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"yes","quote":"if an impact 11 assessment finds that the automated decision-making system 12 produces discriminatory or biased outcomes, the State agency 13 shall cease any utilization, application, or function of such 14 automated decision-making system and of any information 15 produced using the system.","where":"Section 15(b)","specifics":"An agency must stop using any ADS, and any information it produced, if an impact assessment finds discriminatory or biased outcomes.","note":"","caveat":""},{"part":"V","supported":"partial","quote":"A State agency shall not authorize any procurement, 15 purchase, or acquisition of any service or system utilizing, 16 or relying on, automated decision-making systems","where":"Section 10(b)","specifics":"Agencies may not procure systems that use ADS for public assistance, rights-affecting or statutory-right functions unless the system is subject to continuous meaningful human review.","note":"Procurement condition only; no vendor documentation or cooperation duties.","caveat":"the quote cuts off part of the sentence; limited by conditions or exceptions. Quote cuts off before the function list and the 'unless subject to continuous meaningful human review' condition; the specifics sentence is accurate against the full text, and the procurement-only nature is correctly noted."},{"part":"I","supported":"partial","quote":"The impact assessment of an automated 24 decision-making system shall be published on the Internet 25 website of the relevant State agency.","where":"Section 20(b)(1)","specifics":"Each agency must publish its impact assessments on its website (with limited redaction allowed); assessments also go to the Governor and legislative leaders 30 days before implementation (20(a)).","note":"Publication of assessments, not a statewide inventory of systems.","caveat":"limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"any service or program 13 within the control of the State or benefit provided by the 14 State to individuals or households, including, but not limited 15 to, public assistance, cash assistance, grants, child care 16 assistance, housing assistance, unemployment benefits,","where":"Section 5 (definitions)","specifics":"Defines public assistance benefit broadly (cash, child care, housing, unemployment, education assistance, etc.).","note":"The definition excludes federal programs administered by the federal government or the State, which may exclude Medicaid or SNAP; text is ambiguous.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"State agency\" means any Department, public authority, 10 board, bureau, commission, division, office, council, 11 committee, or officer of the State.","where":"Section 5 (definitions)","specifics":"Covers all State agencies and entities acting on their behalf.","note":"","caveat":"a definition, not itself a duty"}]},"IL|SB 1366":{"meta":{"version":"Introduced","date":"2025-01-29","textUrl":"https://legiscan.com/IL/text/SB1366/id/3087783","stateUrl":"https://www.ilga.gov/Legislation/BillStatus/FullText?LegDocId=199201&DocName=10400SB1366&DocNum=1366&DocTypeID=SB&LegID=159412&GAID=18&SessionID=114&SpecSess=&Session=","legiscan":"https://legiscan.com/IL/bill/SB1366/2025","status":1,"statusDate":"2025-01-29"},"q":[{"part":"I","supported":"no","quote":"","where":"","specifics":"No inventory duty.","note":"The text contains no inventory or public list of AI systems; agencies only file impact assessment reports with the Department."},{"part":"A","supported":"partial","quote":"every agency of State 19 government shall submit an impact assessment report on the 20 impact of artificial intelligence on that agency of State 21 government to the Department of Innovation and Technology.","where":"Section 20(a)","specifics":"Every State agency must submit an annual impact assessment report on AI's impact on that agency to the Department of Innovation and Technology starting July 1, 2028.","note":"Report content is unspecified; no bias testing, pre-use testing or discontinuation duty. The Department reports to the General Assembly and Governor starting Jan. 1, 2029 (20(b)).","caveat":"delayed or expires"},{"part":"V","supported":"no","quote":"","where":"","specifics":"No vendor duty.","note":"Section 10 only directs the Department to adopt rules on 'procurement' of AI; the bill imposes no documentation, cooperation or contract duty on vendors and sets no procurement conditions itself."},{"part":"O","supported":"partial","quote":"before January 1, 2028, the Department of Innovation and Technology shall adopt rules establishing policies and procedures concerning the development, procurement, deployment, use, and assessment of artificial intelligence by agencies of State government.","where":"Section 10","specifics":"The Department of Innovation and Technology must adopt rules on development, procurement, deployment, use and assessment of AI by State agencies before 2028.","note":"The Department is a rule-making and reporting body; no penalties or enforcement.","caveat":"delayed or expires"},{"part":"SCOPE","supported":"yes","quote":"Beginning January 1, 2028, unless 13 permitted by rules adopted by the Department of Innovation and 14 Technology, no agency of State government may deploy or use 15 artificial intelligence.","where":"Section 15","specifics":"From 2028, State agencies may not deploy or use any AI unless permitted by the Department's rules.","note":"General AI ban-unless-permitted; no reference to benefits, Medicaid or eligibility decisions.","caveat":"limited by conditions or exceptions; delayed or expires"}]},"GA|HB 147":{"meta":{"version":"Comm Sub","date":"2026-03-17","textUrl":"https://legiscan.com/GA/text/HB147/id/3397656","stateUrl":"https://www.legis.ga.gov/api/legislation/document/20252026/246183","legiscan":"https://legiscan.com/GA/bill/HB147/2025","status":2,"statusDate":"2025-02-20"},"q":[{"part":"I","supported":"yes","quote":"conduct an inventory of38 all systems that employ artificial intelligence which are used to inform or materially39 support a conclusion, decision, or judgment made by any agency.","where":"Section 2, Code Section 50-25-7.9(b)(1)","specifics":"The Georgia Technology Authority must inventory annually, starting by Dec. 31, 2026, all AI systems used to inform or materially support agency decisions, listing system name, vendor, capabilities and uses, and whether an impact assessment was done.","note":"","caveat":""},{"part":"I","supported":"yes","quote":"The authority shall prepare an annual report on the inventory of artificial intelligence49 in use by agencies, as provided for in paragraph (1) of subsection (b) of this Code section. 50 Such report shall be made electronically available to the Governor, Lieutenant Governor,51 and members of the House of Representatives and Senate.","where":"Section 2, 50-25-7.9(c)","specifics":"The Authority must prepare an annual report on the inventory, made electronically available to the Governor, Lieutenant Governor and legislators.","note":"Report goes to officials and is electronically available; it is not stated to be a public website posting.","caveat":""},{"part":"A","supported":"partial","quote":"Whether such system underwent an impact assessment prior t o implementation;","where":"Section 2, 50-25-7.9(b)(1)(C)","specifics":"The inventory records whether each system had a pre-implementation impact assessment; by Dec. 31, 2027 the Authority must set policies for development, procurement, implementation, use and ongoing assessment of AI (50-25-7.9(b)(2)).","note":"No bias testing or impact assessment duty is created directly.","caveat":""},{"part":"O","supported":"partial","quote":"The authority shall:37 (1) Not later than December 31, 2026, and annually thereafter, conduct an inventory","where":"Section 2, 50-25-7.9(b)","specifics":"The Georgia Technology Authority acts as the central body running the inventory, reporting and policy development; all agencies must cooperate (subsection (d)).","note":"No penalties or enforcement.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"systems that employ artificial intelligence which are used to inform or materially39 support a conclusion, decision, or judgment made by any agency.","where":"Section 2, 50-25-7.9(b)(1)","specifics":"Covers AI systems that inform or materially support any agency conclusion, decision or judgment (not limited to benefits).","note":"Section 1 of the bill is unrelated (software licensing limits). Text has line numbers embedded.","caveat":""}]},"RI|H 7119":{"meta":{"version":"Introduced","date":"2026-01-15","textUrl":"https://legiscan.com/RI/text/H7119/id/3320492","stateUrl":"https://webserver.rilegislature.gov/BillText26/HouseText26/H7119.pdf","legiscan":"https://legiscan.com/RI/bill/H7119/2026","status":1,"statusDate":"2026-01-15"},"q":[{"part":"I","supported":"yes","quote":"the department of 12 administration shall conduct an inventory of all systems that employ artificial intelligence and are 13 in use by any state agency.","where":"42-169-3(a)(1)","specifics":"The department of administration must conduct an annual inventory (from Dec. 31, 2027) of all state agency AI systems, listing name, vendor, purpose, whether it makes or informs decisions, and whether an impact assessment was done.","note":"","caveat":"delayed or expires"},{"part":"I","supported":"yes","quote":"The department of administration shall make each inventory conducted pursuant to this 21 section publicly available on the state's open data portal.","where":"42-169-3(a)(2)","specifics":"Each inventory must be posted publicly on the state open data portal.","note":"","caveat":"delayed or expires"},{"part":"A","supported":"yes","quote":"Beginning on February 1, 202 8, no state agency shall implement any system that 21 employs artificial intelligence: 22 (1) Unless the state agency has performed an impact assessment,","where":"42-169-4(b)","specifics":"From Feb. 1, 2028, an agency may not implement an AI system without a prior impact assessment showing no unlawful discrimination or disparate impact, or if the agency head finds the system will cause such discrimination. The department performs ongoing assessments (42-169-3(b), 42-169-4(a)(1)(iv)).","note":"","caveat":"delayed or expires; limited by conditions or exceptions"},{"part":"V","supported":"no","quote":"","where":"","specifics":"The text only lists the vendor in the inventory and has the commission study procurement and NDAs; no vendor obligations or procurement conditions are imposed.","note":""},{"part":"O","supported":"yes","quote":"There is hereby established within the department of administration a permanent 31 artificial intelligence commission (the \"commission\") to monitor the use of artificial intelligence in 32 state government,","where":"42-169-5(a)","specifics":"A permanent 13-member commission (42-169-6) meets at least six times a year to monitor state AI use and reports annually to the governor and legislature (42-169-7).","note":"Advisory body; no enforcement powers or penalties.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"State agency\" means any office, department, board, commission, bureau, division, 8 authority, or public corporation, agency or instrumentality of the state, including all branches of 9 the judiciary.","where":"42-169-2(2)","specifics":"Covers all state agencies and the judiciary, not limited to benefits.","note":"The commission is told to look at disparate outcomes based on receipt of public assistance (42-169-5(b)(8)).","caveat":"a definition, not itself a duty"}]},"OK|HB 3545":{"meta":{"version":"Engrossed","date":"2026-03-12","textUrl":"https://legiscan.com/OK/text/HB3545/id/3394876","stateUrl":"https://www.oklegislature.gov/cf_pdf/2025-26%20ENGR/hB/HB3545%20ENGR.PDF","legiscan":"https://legiscan.com/OK/bill/HB3545/2026","status":2,"statusDate":"2026-03-12"},"q":[{"part":"H","supported":"yes","quote":"No high-risk AI decision shall take effect unless reviewed and approved by a human employee or officer of the state agency who has decision-making authority and is trained in and aware of the limitations of the AI system;","where":"Section 1, subsection D.1","specifics":"No high-risk AI decision may take effect unless a trained human employee with decision-making authority reviews and approves it.","note":"","caveat":""},{"part":"N","supported":"yes","quote":"In all other circumstances in which a human user is interacting with an AI system,","where":"Section 1, subsection D.3","specifics":"People interacting with a state agency AI system must be told so; unreviewed generative AI material must carry an AI disclosure (D.2).","note":"Disclosure of AI use only; no adverse-decision explanation.","caveat":"the quote cuts off part of the sentence. Quote ends before 'the user must be informed that he or she is interacting with an AI system' (next page); specifics are accurate to the full text. D.2 disclosure for unreviewed generative content verified."},{"part":"I","supported":"partial","quote":"OMES shall provide to the Governor, the Speaker of the Oklahoma House of Representatives, and the President Pro Tempore of the Oklahoma State Senate a report summarizing AI systems identified by state agencies, recording which of those systems were prohibited and removed in compliance with this act,","where":"Section 1, subsection G","specifics":"Starting Dec. 1, 2026, OMES must report annually on AI systems identified by agencies, noting which were prohibited and removed and which are allowed, and post reports on its website.","note":"Functions as a public report of systems; it lacks required fields like vendor or purpose.","caveat":"delayed or expires"},{"part":"A","supported":"partial","quote":"Review the use of AI in their computer systems to verify that they comply with the provisions of this act. Any AI system that is prohibited shall be removed;","where":"Section 1, subsection E.1","specifics":"Within nine months all state agencies must review their AI use, remove prohibited systems (including those that classify persons in unlawfully discriminatory ways, C.2) and report compliance to OMES.","note":"One-time compliance review; no impact assessment, testing or ongoing monitoring.","caveat":"delayed or expires"},{"part":"O","supported":"partial","quote":"All state agencies shall take the following actions no later than nine (9) months after the effective date of this act and report their compliance with the Office of Management of Enterprise Services (OMES):","where":"Section 1, subsection E","specifics":"Agencies must report compliance to OMES, which reports annually to the Governor and legislative leaders.","note":"OMES is a reporting recipient; no penalties or enforcement stated.","caveat":"delayed or expires"},{"part":"SCOPE","supported":"yes","quote":"High-risk AI decision\" means an automated determination, classification, scoring, or recommendation generated in whole or in part by an artificial intelligence system that: a. is used as the primary basis for a final agency action affecting an individual's legal rights, eligibility","where":"Section 1, subsection A.4","specifics":"Defines high-risk decisions as those used as the primary basis for final agency action affecting legal rights, eligibility for government benefits or services, civil penalties or legal obligations.","note":"The definition requires that the decision not already be subject to meaningful human review (A.4.c).","caveat":"a definition, not itself a duty; the quote cuts off part of the sentence"},{"part":"SCOPE","supported":"yes","quote":"This act shall apply to all computer systems operated by any state agency,","where":"Section 1, subsection B","specifics":"Applies to all state agency computer systems except higher-education research systems and consumer systems.","note":"","caveat":"limited by conditions or exceptions"}]},"OR|HB 4103":{"meta":{"version":"Engrossed","date":"","textUrl":"https://legiscan.com/OR/text/HB4103/id/3370882","stateUrl":"https://olis.oregonlegislature.gov/liz/2026R1/Downloads/MeasureDocument/HB4103/A-Engrossed","legiscan":"https://legiscan.com/OR/bill/HB4103/2026","status":6,"statusDate":"2026-03-06"},"q":[{"part":"O","supported":"yes","quote":"The Senator Aaron Woods Commission on Artificial Intelligence is es- tablished within the office of Enterprise Information Services.","where":"Section 1(1)","specifics":"Creates a 10-voting-member commission (plus 6 nonvoting, including the Attorney General's designee) that reports annually by Sept. 1 to the Legislative Assembly (Section 1(7)).","note":"Study and advisory body only; no enforcement powers. Section 3 also requires DAS to employ a person responsible for the state's privacy, data protection and AI strategy.","caveat":""},{"part":"I","supported":"no","quote":"","where":"","specifics":"The commission is to 'identify uses' of AI systems that create high risk (Section 1(2)(c)) but no inventory is required or published.","note":""},{"part":"SCOPE","supported":"yes","quote":"Identify uses of artificial intelligence systems by the state that present or create a high risk to individuals, such as risks to individuals’ safety, employment rights, civil rights or constitutional rights;","where":"Section 1(2)(c)","specifics":"The commission must identify high-risk state AI uses and recommend policy; it does not regulate agencies directly.","note":"No agency duties besides assisting the commission (Section 1(6)); no mention of benefits or Medicaid.","caveat":"limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"All agencies of state government, as defined in ORS 174.111, are directed to assist the commission in the performance of the duties of the commission","where":"Section 1(6)","specifics":"State agencies must assist the commission and provide information it considers necessary.","note":"","caveat":"limited by conditions or exceptions"}]},"NH|SB 657":{"meta":{"version":"Amended","date":"2026-03-26","textUrl":"https://legiscan.com/NH/text/SB657/id/3436397","stateUrl":"https://gc.nh.gov/bill_status/legacy/bs2016/billText.aspx?sy=2026&txtFormat=html&v=HA&id=2483","legiscan":"https://legiscan.com/NH/bill/SB657/2026","status":2,"statusDate":"2026-03-27"},"q":[{"part":"I","supported":"yes","quote":"The commissioner shall maintain a current inventory of all artificial intelligence systems, as defined in RSA 5-D:1, deployed by executive branch agencies.","where":"Section 3, RSA 21-R:9-b, I","specifics":"The IT commissioner must keep a current inventory of all executive branch AI systems with name, vendor, using agencies, purpose, whether used in decisions affecting rights or benefits, and deployment date; it is posted on the department website and updated at least annually.","note":"Version amended by the House; bill died when chambers did not agree.","caveat":""},{"part":"I","supported":"yes","quote":"The inventory shall be posted on the department's website and updated not less than annually.","where":"Section 3, RSA 21-R:9-b, I","specifics":"The inventory must be posted publicly and updated at least yearly.","note":"","caveat":""},{"part":"O","supported":"partial","quote":"On or before October 1 of each year, the commissioner, in consultation with the information technology council, shall submit a report to the president of the senate, the speaker of the house of representatives, the senate clerk, the house clerk, the governor, and the state library.","where":"Section 3, RSA 21-R:9-b, II","specifics":"The commissioner must report annually to legislative leaders and the governor, including an assessment of agency compliance with RSA 5-D and any incidents involving unauthorized use or disclosure of personal information; the IT council advises on AI (Section 1).","note":"Reporting and advisory only; no enforcement powers or penalties.","caveat":""},{"part":"A","supported":"no","quote":"","where":"","specifics":"The annual report includes an assessment of agency compliance with RSA 5-D, but the bill itself imposes no impact assessment, testing or bias monitoring duty on agencies.","note":""},{"part":"SCOPE","supported":"yes","quote":"whether the system is used in making decisions affecting the rights or benefits of individuals,","where":"Section 3, RSA 21-R:9-b, I","specifics":"The inventory flags systems used to make decisions affecting individuals' rights or benefits.","note":"This is the only reference to benefits; the bill is mainly about inventory, reporting and advisory committees.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"AN ACT relative to the use of information technology and artificial intelligence systems by state agencies.","where":"Title","specifics":"Applies to executive branch agencies' AI use through the Department of Information Technology.","note":"","caveat":"findings or preamble, not operative law"}]},"NH|HB 1506":{"meta":{"version":"Introduced","date":"","textUrl":"https://legiscan.com/NH/text/HB1506/id/3289995","stateUrl":"https://gc.nh.gov/bill_status/legacy/bs2016/billText.aspx?sy=2026&id=1711&txtFormat=html","legiscan":"https://legiscan.com/NH/bill/HB1506/2026","status":1,"statusDate":"2025-12-10"},"q":[{"part":"SCOPE","supported":"yes","quote":"This bill authorizes commissioners or heads of state agencies to apply for an exception to the restricted uses for which artificial intelligence may be used by state agencies.","where":"Analysis","specifics":"Lets any state agency seek an exception to RSA 5-D's restrictions on AI use.","note":"The restrictions in RSA 5-D are not in this text.","caveat":"findings or preamble, not operative law"},{"part":"SCOPE","supported":"yes","quote":"The executive council shall review requests for an exception to the applicability of RSA 5-D and determine whether an exception shall be accepted or denied.","where":"Section 4, RSA 4:49","specifics":"The executive council decides on each exception request.","note":"","caveat":""}]},"NM|SB 68":{"meta":{"version":"Introduced","date":"2026-01-22","textUrl":"https://legiscan.com/NM/text/SB68/id/3329640","stateUrl":"https://www.nmlegis.gov/Sessions/26%20Regular/bills/senate/SB0068.pdf","legiscan":"https://legiscan.com/NM/bill/SB68/2026","status":1,"statusDate":"2026-01-22"},"q":[{"part":"H","supported":"yes","quote":"require an authorized human employee to make a final consequential decision in the course of the employee's employment, regardless of what the artificial intelligence or automated decision tool recommends;","where":"Section 3.B(3)","specifics":"Each public body's AI policy must require an authorized human employee to make the final consequential decision regardless of the AI recommendation.","note":"Applies to decisions on education, employment, financial services, housing, health care, insurance and legal services.","caveat":""},{"part":"I","supported":"no","quote":"","where":"","specifics":"Section 3.C only requires state agencies to make their AI and automated decision tool policies available to the public on request; it does not list systems.","note":""},{"part":"SCOPE","supported":"yes","quote":"consequential decision\" means a decision that has a material, legal or similarly significant effect on the provision or denial of, or the cost or terms of, the following goods or services to a person:","where":"Section 2.C","specifics":"Consequential decisions cover education enrollment, employment, financial or lending service, housing, health care service, insurance and legal service.","note":"Public benefits, Medicaid and SNAP are not listed by name.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"A public body shall establish a policy regarding the authorized uses of artificial intelligence and automated decision tools and technology resources by employees.","where":"Section 3.A","specifics":"Every public body (state agencies, counties, municipalities, school districts, universities) must set a policy on employee use of AI and automated decision tools, and train staff (Section 4).","note":"Policy and training bill; no notice, assessment, vendor or oversight-body provisions.","caveat":""}]},"FL|S 146":{"meta":{"version":"Introduced","date":"2025-10-09","textUrl":"https://legiscan.com/FL/text/S0146/id/3272497","stateUrl":"https://www.flsenate.gov/Session/Bill/2026/146/BillText/Filed/HTML","legiscan":"https://legiscan.com/FL/bill/S0146/2026","status":6,"statusDate":"2026-03-13"},"q":[{"part":"I","supported":"partial","quote":"A list of state agencies that use artificial 42 intelligence.","where":"Section 1(2)(a)","specifics":"The Florida Digital Service must study and list which state agencies use AI, for what purposes and at what cost, and report to the Governor and Legislature by March 1, 2027.","note":"One-time study, not a continuing public inventory; no requirement that the list be published.","caveat":"delayed or expires"},{"part":"SCOPE","supported":"yes","quote":"The Florida Digital Service shall conduct a study that 37 addresses the impact of state agencies procuring, implementing, 38 or operating artificial intelligence-powered technology.","where":"Section 1(2)","specifics":"Study-only bill covering state agency AI procurement and use; it does not regulate any decisions.","note":"No notice, assessment, human review, vendor or enforcement duties.","caveat":""}]},"MS|HB 1640":{"meta":{"version":"Engrossed","date":"2026-02-16","textUrl":"https://legiscan.com/MS/text/HB1640/id/3363778","stateUrl":"https://billstatus.ls.state.ms.us/documents/2026/html/HB/1600-1699/HB1640PS.htm","legiscan":"https://legiscan.com/MS/bill/HB1640/2026","status":6,"statusDate":"2026-03-30"},"q":[{"part":"SCOPE","supported":"yes","quote":"The Department of Human Services shall employ automated commercial wage verification services regulated under the Fair Credit Reporting Act for the purpose of acquiring current employment and income information for eligibility determination and ongoing monitoring for continued eligibility for public benefit programs, including SNAP and TANF benefits.","where":"Section 1, new Section 43-12-18","specifics":"Requires the Department of Human Services to use automated wage-verification services to check eligibility and ongoing eligibility for public benefit programs including SNAP and TANF.","note":"Inverse of a safeguard bill: it mandates automated data use in eligibility with no notice, human review, assessment, vendor or oversight provisions. The only related safeguard is indirect: the services are FCRA-regulated.","caveat":""}]},"AK|SB 2":{"meta":{"version":"Introduced","date":"2025-01-10","textUrl":"https://legiscan.com/AK/text/SB2/id/3049420","stateUrl":"https://www.akleg.gov/PDF/34/Bills/SB0002A.PDF","legiscan":"https://legiscan.com/AK/bill/SB2/2025","status":1,"statusDate":"2025-01-22"},"q":[{"part":"I","supported":"yes","quote":"Every two years, th e department shall conduct 20 an inventory of all state agency systems that employ generative artificial intelligence 21 for consequential decisions.","where":"Sec. 44.99.700(a)","specifics":"The Department of Administration must inventory, every two years, state agency generative AI systems used for consequential decisions (name, vendor, capabilities, impact assessment status and date), and publish it on its website (44.99.700(c)).","note":"Inventory entries for Department of Public Safety systems are withheld from publication, but those systems are still inventoried.","caveat":"limited by conditions or exceptions"},{"part":"N","supported":"yes","quote":"A state agency that uses a system that employs generative artificial 28 intelligence for consequential decisions shall 29 (1) notify each individual who may be legally or significantly affected 30 by the use of the system;","where":"Sec. 44.99.720(a)(1)","specifics":"Agencies must notify each individual who may be legally or significantly affected by the system and get consent before collecting sensitive personal data for it.","note":"Notice of AI use; no explicit explanation of reasons for an adverse decision.","caveat":"limited by conditions or exceptions"},{"part":"A","supported":"yes","quote":"the 4 head of a state agency that uses a system that employs generati ve artificial intelligence 5 for consequential decisions s hall conduct an impact assessment","where":"Sec. 44.99.710(a)","specifics":"Agency heads must conduct an impact assessment at least every two years covering efficacy, human oversight, appeals, discrimination or disparate impact and effects on individuals; regulations must also require an assessment before implementation and ongoing assessment (44.99.740(a)).","note":"","caveat":"limited by conditions or exceptions"},{"part":"H","supported":"yes","quote":"provide an appeals process that includes manual human revi ew for 3 an individual who is legally or significantly affected by the use of the system;","where":"Sec. 44.99.720(a)(3)","specifics":"Agencies must provide an appeals process with manual human review for anyone legally or significantly affected by the system.","note":"","caveat":"limited by conditions or exceptions"},{"part":"V","supported":"partial","quote":"A s t a t e a g e n c y m a y c o n t r a c t w i t h a p e r s o n f o r a s y s t e m t h at employs 17 artificial intelligence for consequential decisions only if the person has implemented 18 security and privacy controls","where":"Sec. 44.99.720(d)","specifics":"Agencies may contract for such systems only with vendors that have NIST SP 800-53 Rev. 5 security and privacy controls; regulations govern procurement (44.99.740(a)(1)).","note":"Procurement condition limited to security and privacy; no vendor documentation or bias duties.","caveat":""},{"part":"O","supported":"yes","quote":"An individual who suffers harm 11 as a result of a violation of AS 44.99.700 - 44.99.730, a viola tion of a regulation 12 adopted under AS 44.99.740, or gross negligence or reckless or intentional misconduct 13 relating to the use of artificial intelligence by a state agency may bring a civil action in 14 the superior court against the state agency.","where":"Sec. 44.99.750(a)","specifics":"Individuals harmed by violations may sue the state agency in superior court for damages, punitive damages and attorney fees (44.99.750(b)); the Department of Administration adopts regulations (44.99.740).","note":"No attorney general role or cure period.","caveat":""},{"part":"SCOPE","supported":"yes","quote":"consequential decision\" means a conclusion, decision, or 8 judgment by a state agency that can affect an individual's lega l rights, employment, 9 finances, health, or licensure;","where":"Sec. 44.99.770(4)","specifics":"Consequential decisions are agency decisions affecting legal rights, employment, finances, health or licensure.","note":"Benefits, Medicaid and SNAP are not named; the definition likely reaches them through finances or health.","caveat":"a definition, not itself a duty"},{"part":"SCOPE","supported":"yes","quote":"A state agency may not use a system that employs artificial intelligence for 8 consequential decisions if the system involves 9 (1) biometric identification, including facial recognition; 10 (2) emotion recognition; 11 (3) cognitive behavioral manipulation of individuals or groups; or 12 (4) social scoring.","where":"Sec. 44.99.720(b)","specifics":"Bans agency use of AI for consequential decisions that involves biometric identification, emotion recognition, cognitive behavioral manipulation or social scoring, or foreign-adversary hosted data (720(c)).","note":"Inventory entries for Department of Public Safety systems are withheld from publication, but those systems are still inventoried.","caveat":"limited by conditions or exceptions. Note says inventory does not apply to Department of Public Safety systems; 44.99.760(a) does not list 44.99.700, only 710, 720(a), 720(b)(1), 730 and regs (760(b) just keeps their entries out of the published inventory)."}]},"MA|H 77":{"meta":{"version":"Introduced","date":"2025-02-27","textUrl":"https://legiscan.com/MA/text/H77/id/3168280","stateUrl":"https://malegislature.gov/Bills/194/H77.pdf","legiscan":"https://legiscan.com/MA/bill/H77/2025","status":1,"statusDate":"2025-02-27"},"q":[{"part":"H","supported":"partial","quote":"or any entity acting on behalf of an 578 agency or department, shall be prohibited from, directly or indirectly, utilizing or applying any 579 automated decision system in performing any function that: (i) is related to the delivery of any 580 public assistance benefit;","where":"Section 2, G.L. c. 30, Section 66","specifics":"State agencies and their contractors may not use any ADS for public assistance benefit delivery, rights-affecting or constitutional-right functions unless a law specifically authorizes it.","note":"This is a ban-unless-authorized rule, not a human-review rule. The human-oversight provisions (Chapter 149B, Section 5(b)) apply to employer decisions about workers, not to agency benefit decisions.","caveat":"the quote cuts off part of the sentence; limited by conditions or exceptions. Ban-unless-authorized, not a human-review rule; quote cuts off before the 'unless specifically authorized in law' limit and clauses (ii)-(iii). Text is the as-filed H.77 (docket 1458), not necessarily the committee-reported version."},{"part":"A","supported":"yes","quote":"No state agency shall utilize or apply any automated decision system unless the agency, 597 or an entity acting on behalf of such state agency, shall have conducted an impact assessment for 598 the application and use of such automated decision system. Following the first impact 599 assessment, an impact assessment shall be conducted at least once every two years.","where":"Section 3, G.L. c. 30B, Section 24","specifics":"No state agency may use an ADS without an impact assessment, repeated at least every two years and before any material change; it must test for accuracy, fairness, bias and discrimination.","note":"Impact assessment must include bias testing (item iv); a discriminatory finding requires the agency to cease use (item c).","caveat":""},{"part":"A","supported":"yes","quote":"if an impact 633 assessment finds that the automated decision-making system produces discriminatory or biased 634 outcomes, the state agency shall cease any utilization, application, or function of such automated 635 decision-making system, and of any information produced using that system.","where":"Section 3, G.L. c. 30B, Section 24(c)","specifics":"An agency must stop using an ADS, and any information it produced, if its impact assessment finds discriminatory or biased outcomes.","note":"","caveat":""},{"part":"N","supported":"partial","quote":"vi) the notification mechanism or procedure, if any, by which individuals impacted by the 629 utilization of the automated decision-making system may be notified of the use of such 630 automated decision-making system and of the individual’s personal data, and informed of their 631 rights and options relating to such use.","where":"Section 3, G.L. c. 30B, Section 24(b)(vi)","specifics":"Impact assessments must describe any mechanism for notifying affected individuals of ADS use and their rights.","note":"Only an assessment item, 'if any'. Detailed notice duties in Chapter 149B Section 4 apply to employers' hiring tools.","caveat":"limited by conditions or exceptions. Only an item an assessment must describe, 'if any'; not an enforceable notice duty to affected people. Subsection label '(b)' is not visible in the extracted text."},{"part":"I","supported":"partial","quote":"The impact statement of an automated decision-making system that is approved and utilized, 640 shall be published on the website of the relevant agency.","where":"Section 3, G.L. c. 30B, Section 24(d)","specifics":"Impact assessments must go to the governor, Senate president and House speaker at least 60 days before implementation and be published on the agency's website, with limited redaction.","note":"Publication of assessments, not a full inventory of systems.","caveat":""},{"part":"V","supported":"partial","quote":"No executive office, department, division, agency, or commission of the commonwealth 588 shall authorize any procurement, purchase, or acquisition of any service or system utilizing, or 589 relying on, automated decision systems, except where the use of such system is specifically 590 authorized in law.","where":"Section 3, G.L. c. 30B, Section 24","specifics":"Agencies may not procure services or systems relying on ADS unless a law specifically authorizes the use.","note":"Procurement bar only; vendor documentation duties are in the employment tools part (Chapter 149B Section 3(c)).","caveat":""},{"part":"O","supported":"partial","quote":"The Office of the Attorney General shall promulgate additional procedures, rules, or 546 regulations in order to further the Commonwealth’s interest in protecting consumers and the 547 public good from violations of privacy rights and harms resulting from the use of artificial 548 intelligence and automated-decision systems.","where":"Chapter 149B (end of Section 6, before Section 7)","specifics":"The attorney general must issue regulations on AI and ADS, considering bias testing, disclosures and notice.","note":"Mostly located in the employment chapter; enforcement there is by civil action of employees (Section 7). No enforcement mechanism is tied to the agency ADS sections.","caveat":"the quote cuts off part of the sentence"},{"part":"SCOPE","supported":"yes","quote":"Any agency or department of the commonwealth, or any entity acting on behalf of an 578 agency or department, shall be prohibited from, directly or indirectly, utilizing or applying any 579 automated decision system in performing any function that: (i) is related to the delivery of any 580 public assistance benefit;","where":"Section 2, G.L. c. 30, Section 66","specifics":"Core agency provision: ban on agency ADS for public assistance benefits, rights or welfare unless specifically authorized by law.","note":"Most of the bill (Chapter 149B) concerns electronic monitoring and automated employment decision tools used by employers.","caveat":"the quote cuts off part of the sentence; limited by conditions or exceptions"},{"part":"SCOPE","supported":"yes","quote":"An automated decision system is any computational process, automated system, or 592 algorithm utilizing machine learning, statistical modeling, data analytics, artificial intelligence, 593 or similar methods that issues an output, including a score, classification, ranking, or 594 recommendation, that is used to assist or replace human decision making on decisions that 595 impact natural persons.","where":"Section 3, G.L. c. 30B, Section 24","specifics":"Defines ADS broadly as any computational process that issues a score, classification, ranking or recommendation used to assist or replace human decisions affecting people.","note":"","caveat":"a definition, not itself a duty"}]},"PA|HB 1925":{"meta":{"version":"Amended","date":"2026-09-29","textUrl":"https://legiscan.com/PA/text/HB1925/id/3460784","stateUrl":"https://www.palegis.us/legislation/bills/text/PDF/2025/0/HB1925/PN3963","legiscan":"https://legiscan.com/PA/bill/HB1925/2025","status":2,"statusDate":"2026-09-30"},"q":[{"part":"N","supported":"yes","quote":"An MA or CHIP managed care plan shall disclose to a participating network provider and all enrollees in plain language if artificial intelligence models or systems are or will be used in the utilization review process of the MA or CHIP managed care plan.","where":"Section 3, § 4102(a)","specifics":"MA (Medicaid) and CHIP managed care plans must tell network providers and all enrollees, in plain language, if AI is or will be used in utilization review, and post it on their website (4102(b)); the department sets nature and frequency (4102(c)).","note":"Disclosure of AI use; no requirement to explain individual adverse decisions.","caveat":"delayed or expires"},{"part":"H","supported":"yes","quote":"Based on the review under paragraph (1), exercise judgment independent of any recommendations","where":"Section 3, § 4105(A)(3)","specifics":"Before denying, reducing or terminating benefits, a participating health care provider must review individual clinical records, document the review and use independent judgment, not AI recommendations.","note":"Provider-level review rather than an enrollee appeal.","caveat":"delayed or expires; the quote cuts off part of the sentence"},{"part":"H","supported":"yes","quote":"The artificial intelligence model or system must not supersede decision making of the health care provider conducting the utilization review.","where":"Section 3, § 4103(b)(3)","specifics":"The AI may not replace the health care provider's decision making in utilization review.","note":"","caveat":"delayed or expires"},{"part":"A","supported":"yes","quote":"The performance, use and outcomes of the artificial intelligence model or system must be reviewed at least","where":"Section 3, § 4103(b)(7)","specifics":"Plans must review the AI model's performance, use and outcomes at least annually (amended from quarterly) and revise it as needed; AI must not discriminate or create foreseeable material risks of harm ((b)(4), (b)(9)).","note":"Text contains both struck and inserted wording ('quarterly ANNUALLY').","caveat":"delayed or expires; the quote cuts off part of the sentence. Quote ends at 'at least' so omits the frequency; text shows 'quarterly' struck and 'ANNUALLY' inserted, so annual is correct for the amended text. (b)(4) and (b)(9) exist as stated."},{"part":"A","supported":"yes","quote":"Policies and procedures for implementing, using and monitoring the use of the artificial intelligence models or systems.","where":"Section 3, § 4103(c)(1)","specifics":"Plans must keep policies and procedures, a governance structure, and a process to validate and monitor compliance; plans file an annual AI compliance statement with the department (4104).","note":"","caveat":"delayed or expires"},{"part":"V","supported":"partial","quote":"AN MA OR CHIP MANAGED CARE PLAN MAY REQUIRE A THIRD-PARTY VENDOR PROVIDING ARTIFICIAL INTELLIGENCE MODELS OR SYSTEMS GOVERNED BY THIS CHAPTER TO COMPLY IN CONTRACT WITH THE REQUIREMENTS OF THIS CHAPTER.","where":"Section 3, § 4108","specifics":"Plans using third-party AI vendors must set up internal review and governance to ensure compliance and may require vendors to comply by contract.","note":"Permissive ('may require'); no direct vendor duties.","caveat":"delayed or expires; permissive (\"may\"), not mandatory; the quote cuts off part of the sentence"},{"part":"O","supported":"yes","quote":"The department shall ensure compliance with this chapter.","where":"Section 3, § 4107(a)","specifics":"The Department of Human Services ensures compliance, may investigate and request information (4107(b)), may impose civil penalties up to $10,000 for knowing violations and $5,000 for negligent ones (4110(a)), and the Attorney General has exclusive authority for unfair-trade-practice actions (4110(c)).","note":"Aggregate cap per entity per year shown as $250,000 struck and $100,000 inserted. Department may also bar new enrollments (4110(e)) and require a plan of correction (4111); first-time negligent good-faith violators may get a plan of correction in lieu of penalty.","caveat":"delayed or expires"},{"part":"SCOPE","supported":"yes","quote":"Medical Assistance or Children's Health Insurance Program managed care plan\" or \"MA or CHIP managed care plan.\"","where":"Section 3, § 4101 (definitions)","specifics":"Defines the regulated entities as MA and CHIP managed care plans, which are Medicaid and CHIP managed care organizations.","note":"Definition continues after the quoted text; the bill also adds Title 35 (facilities) and Title 40 (insurers) chapters, not reviewed here.","caveat":"delayed or expires; a definition, not itself a duty; the quote cuts off part of the sentence"},{"part":"SCOPE","supported":"yes","quote":"This chapter shall not apply to artificial intelligence models or systems used for administrative, scheduling or other purposes not pertaining to the decision to deny, reduce or terminate benefits.","where":"Section 3, § 4109","specifics":"Covers only AI used in decisions to deny, reduce or terminate benefits for a health care service; administrative AI is exempt.","note":"","caveat":"delayed or expires; limited by conditions or exceptions"}]}};
